import { extractClientGeo } from './clientGeo'

/**
 * 基于 Cache API 的简易边缘限流（同 POP 内有效，防刷够用）
 */
export async function enforceRateLimit(options: {
  key: string
  limit: number
  windowSec: number
}): Promise<{ ok: true } | { ok: false; retryAfterSec: number }> {
  const { key, limit, windowSec } = options
  const cacheKey = new Request(`https://ratelimit.internal/${encodeURIComponent(key)}`)
  const cache = caches.default

  try {
    const hit = await cache.match(cacheKey)
    let count = 0
    if (hit) {
      count = Number(hit.headers.get('X-Count') || '0') || 0
    }
    count += 1
    if (count > limit) {
      return { ok: false, retryAfterSec: windowSec }
    }
    const res = new Response('1', {
      headers: {
        'X-Count': String(count),
        'Cache-Control': `max-age=${windowSec}`
      }
    })
    await cache.put(cacheKey, res)
    return { ok: true }
  } catch {
    // Cache 不可用时放行，避免误杀
    return { ok: true }
  }
}

export function clientIp(c: {
  req: { header: (n: string) => string | undefined; raw?: Request }
}): string {
  if (c.req.raw) {
    const geo = extractClientGeo(c.req.raw)
    if (geo.ip) return geo.ip
  }
  return (
    c.req.header('cf-connecting-ip') ||
    c.req.header('true-client-ip') ||
    c.req.header('x-real-ip') ||
    'unknown'
  )
}
