/** 站点 AI 配置优先，缺省回退全局 settings */
async function getAiConfigValue(
  env: Env,
  key: string,
  siteId?: string | null
): Promise<string | null> {
  const sid = (siteId || '').trim()
  if (sid) {
    try {
      const siteMap = await getSiteSettingsMap(env.DB, sid)
      const v = siteMap[key]
      if (v != null && String(v).trim() !== '') return String(v)
    } catch {
      /* ignore */
    }
  }
  return getSystemSetting(env.DB, key)
}

