export function resolveCfModelId(model: string): string {
  const raw = (model || '').trim()
  if (!raw) return CF_ULTIMATE_MODEL
  return DEPRECATED_MODEL_MAP[raw] || raw
}

/** 读取库内模型池时自动改写已下线 model id，避免每次调用再撞墙 */
export function normalizeModelPool(channels: AiModelChannel[]): AiModelChannel[] {
  return channels.map(ch => {
    if (ch.type !== 'cf_workers_ai') return ch
    const next = resolveCfModelId(ch.model)
    return next === ch.model ? ch : { ...ch, model: next }
  })
}

