import { apiMessagesZhCN } from './apiMessages.zh-CN'
import type { ApiLocale } from './resolveApiLocale'

const CATALOGS: Partial<Record<ApiLocale, Record<string, string>>> = {
  'zh-CN': apiMessagesZhCN,
  // Traditional Chinese: reuse Simplified for API errors until a dedicated catalog exists
  'zh-TW': apiMessagesZhCN
}

const MSG_KEYS = new Set(['msg', 'message', 'error', 'error_message', 'detail'])

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/** Match catalog keys that still contain `${var}` placeholders against runtime strings. */
function matchTemplate(enTemplate: string, text: string, zhTemplate: string): string | null {
  if (!enTemplate.includes('${')) return null
  const tokenRe = /\$\{([^}]+)\}/g
  const names: string[] = []
  let pattern = ''
  let last = 0
  let m: RegExpExecArray | null
  while ((m = tokenRe.exec(enTemplate))) {
    pattern += escapeRegExp(enTemplate.slice(last, m.index))
    pattern += '(.+?)'
    names.push(m[1])
    last = m.index + m[0].length
  }
  pattern += escapeRegExp(enTemplate.slice(last))
  const re = new RegExp(`^${pattern}$`)
  const hit = text.match(re)
  if (!hit) return null
  let out = zhTemplate
  names.forEach((name, i) => {
    out = out.split(`\${${name}}`).join(hit[i + 1] ?? '')
  })
  return out
}

/** Translate an English source API string for the given locale. */
export function apiT(locale: ApiLocale, text: string): string {
  if (!text || locale === 'en') return text
  const catalog = CATALOGS[locale]
  if (!catalog) return text

  const exact = catalog[text]
  if (exact) return exact

  for (const [en, zh] of Object.entries(catalog)) {
    const templated = matchTemplate(en, text, zh)
    if (templated != null) return templated
  }

  // Prefix match for dynamic suffixes: "Failed to load categories: " + err
  let bestKey = ''
  let bestVal = ''
  for (const [en, zh] of Object.entries(catalog)) {
    if (en.endsWith(':') && text.startsWith(en) && en.length > bestKey.length) {
      bestKey = en
      bestVal = zh
    }
  }
  if (bestKey) return bestVal + text.slice(bestKey.length)

  return text
}

function translateValue(locale: ApiLocale, value: unknown): unknown {
  if (typeof value === 'string') return apiT(locale, value)
  if (Array.isArray(value)) return value.map(v => translateValue(locale, v))
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {}
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = MSG_KEYS.has(k) ? translateValue(locale, v) : v
    }
    return out
  }
  return value
}

/** Deep-translate known message fields on a JSON body. */
export function translateApiJsonBody(locale: ApiLocale, body: unknown): unknown {
  if (locale === 'en' || body == null) return body
  return translateValue(locale, body)
}
