/**
 * 从入站访客请求提取真实客户端 IP 与 CF 边缘地理信息。
 * 排除 Cloudflare Worker 出站/内网地址，避免画像误记为「CF 机房」。
 */

export type ClientGeo = {
  ip: string
  country: string
  city: string
  region: string
  isp: string
  timezone: string
}

/** Cloudflare Worker 跨区子请求等常见基础设施地址 */
const CF_INFRA_IPS = new Set([
  '2a06:98c0:3600::103',
  '2a06:98c0:3600::103'.toLowerCase()
])

function normalizeIp(raw: string | null | undefined): string {
  if (!raw) return ''
  let s = String(raw).trim()
  if (!s) return ''
  // IPv4-mapped IPv6 [::ffff:1.2.3.4]
  const mapped = s.match(/^::ffff:(\d{1,3}(?:\.\d{1,3}){3})$/i)
  if (mapped) s = mapped[1]
  // 带端口的 IPv4
  if (/^\d{1,3}(?:\.\d{1,3}){3}:\d+$/.test(s)) s = s.split(':')[0]
  return s
}

function isPrivateOrLocalIp(ip: string): boolean {
  const v = ip.toLowerCase()
  if (!v) return true
  if (v === '::1' || v === '0.0.0.0' || v === '127.0.0.1') return true
  if (v.startsWith('fc') || v.startsWith('fd') || v.startsWith('fe80:')) return true
  if (/^10\./.test(v)) return true
  if (/^127\./.test(v)) return true
  if (/^192\.168\./.test(v)) return true
  if (/^169\.254\./.test(v)) return true
  const m = v.match(/^172\.(\d+)\./)
  if (m) {
    const n = Number(m[1])
    if (n >= 16 && n <= 31) return true
  }
  return false
}

/** 是否为不可用于访客画像的地址（内网 / CF 基础设施） */
export function isUnusableClientIp(ip: string): boolean {
  const v = normalizeIp(ip)
  if (!v) return true
  if (CF_INFRA_IPS.has(v.toLowerCase())) return true
  if (isPrivateOrLocalIp(v)) return true
  return false
}

function pickFirstUsableIp(candidates: Array<string | null | undefined>): string {
  for (const c of candidates) {
    const ip = normalizeIp(c)
    if (ip && !isUnusableClientIp(ip)) return ip
  }
  return ''
}

function parseForwardedFor(header: string | null): string[] {
  if (!header) return []
  return header
    .split(',')
    .map(p => normalizeIp(p))
    .filter(Boolean)
}

/**
 * @param request 浏览器直达 Worker 的原始 Request（勿用 DO 内部子请求）
 * @param clientTimezoneHint 浏览器 Intl 时区，作 CF timezone 缺失时的兜底
 */
export function extractClientGeo(
  request: Request,
  clientTimezoneHint?: string | null
): ClientGeo {
  const h = request.headers
  const cf = request.cf as
    | {
        country?: string
        city?: string
        region?: string
        timezone?: string
        asOrganization?: string
        clientIp?: string
      }
    | undefined

  const xff = parseForwardedFor(h.get('x-forwarded-for') || h.get('X-Forwarded-For'))

  // 优先 CF 权威访客 IP；x-real-ip 在直连 Worker 时通常被剥离，且易被代理写成边缘地址，仅作末位候选
  const ip = pickFirstUsableIp([
    h.get('cf-connecting-ip'),
    h.get('CF-Connecting-IP'),
    h.get('true-client-ip'),
    h.get('True-Client-IP'),
    cf?.clientIp,
    ...xff,
    h.get('x-real-ip'),
    h.get('X-Real-IP')
  ])

  const countryRaw =
    (cf?.country && cf.country !== 'XX' ? cf.country : '') ||
    h.get('cf-ipcountry') ||
    h.get('CF-IPCountry') ||
    ''
  const country = countryRaw === 'T1' ? 'Tor' : countryRaw

  const city = (cf?.city || '').trim()
  const region = (cf?.region || '').trim()
  const isp = (cf?.asOrganization || '').trim()
  const timezone =
    (cf?.timezone || '').trim() ||
    (clientTimezoneHint || '').trim() ||
    ''

  return { ip, country, city, region, isp, timezone }
}

/** 是否有可用地理字段（至少 IP 或国家） */
export function hasUsableGeo(geo: ClientGeo): boolean {
  return Boolean(geo.ip || geo.country)
}
