import { Hono } from 'hono'
import type { Env } from '../types'
import {
  getGroups,
  createGroup,
  updateGroup,
  deleteGroup,
  setConversationGroup
} from '../db/groups'
import { isErrorResponse, requireAgent } from '../middleware/auth'

export const groupsRouter = new Hono<{ Bindings: Env }>()

groupsRouter.get('/groups', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const list = await getGroups(c.env.DB)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

groupsRouter.post('/groups', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const { name, color } = await c.req.json()
    if (!name) return c.json({ success: false, message: 'Group name cannot be empty' }, 400)
    const item = await createGroup(c.env.DB, name, color)
    return c.json({ success: true, data: item })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

groupsRouter.put('/groups/:id', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    const { name, color } = await c.req.json()
    await updateGroup(c.env.DB, id, name, color)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

groupsRouter.delete('/groups/:id', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    await deleteGroup(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

groupsRouter.post('/conversations/:id/group', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const convId = c.req.param('id')
    const { group_id } = await c.req.json()
    if (!group_id) return c.json({ success: false, message: 'Specify a group' }, 400)
    await setConversationGroup(c.env.DB, convId, group_id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
