import type {
  FormFieldConfig,
  FormFieldLocale,
  FormLocaleBundle,
  ResolvedFormField,
  WidgetItem,
  WidgetLocaleBundle,
  WidgetType
} from './types'

/** 按访客语种解析文案包：当前语 → 默认语 → en → 任意已有 */
export function pickLocaleBundle<T extends Record<string, unknown>>(
  map: Record<string, T> | null | undefined,
  lang: string,
  defaultLang?: string
): T | null {
  if (!map || typeof map !== 'object') return null
  const norm = (c: string) => c.toLowerCase().replace(/_/g, '-')
  const want = norm(lang)
  if (map[lang]) return map[lang]
  const hit = Object.entries(map).find(([k]) => norm(k) === want)
  if (hit) return hit[1]
  if (defaultLang && map[defaultLang]) return map[defaultLang]
  if (map.en) return map.en
  if (map['en-US']) return map['en-US']
  if (map['zh-CN']) return map['zh-CN']
  const first = Object.values(map)[0]
  return first || null
}

export function emptyFormLocaleBundle(): FormLocaleBundle {
  return { title: '', description: '', button_text: '', success_message: '', fields: {} }
}

export function emptyWidgetLocaleBundle(): WidgetLocaleBundle {
  return { title: '', fields: {} }
}

/** 将字段骨架 + 单语种文案解析为渲染用字段；选项提交值为 option.key */
export function resolveFormFields(
  fields: FormFieldConfig[],
  locale: FormLocaleBundle | WidgetLocaleBundle | null | undefined
): ResolvedFormField[] {
  const fieldLocales = locale && 'fields' in locale ? locale.fields || {} : {}
  return fields.map(f => {
    const loc: FormFieldLocale = fieldLocales[f.key] || { label: f.key }
    const needsOpts = ['radio', 'checkbox', 'select', 'multi-select'].includes(f.type)
    let options: Array<{ key: string; label: string }> | undefined
    if (needsOpts) {
      if (loc.options && loc.options.length > 0) {
        options = loc.options.filter(o => o.key && o.label)
      } else if (f.options && f.options.length > 0) {
        options = f.options.map(o => ({ key: o.key, label: o.key }))
      } else {
        options = []
      }
    }
    return {
      id: f.id,
      key: f.key,
      type: f.type,
      required: f.required,
      label: loc.label || f.key,
      placeholder: loc.placeholder,
      options
    }
  })
}

export function resolveFormShell(
  translations: Record<string, FormLocaleBundle> | null | undefined,
  lang: string,
  defaultLang?: string
): {
  title: string
  description: string
  button_text: string
  success_message: string
  locale: FormLocaleBundle | null
} {
  const locale = pickLocaleBundle(translations, lang, defaultLang)
  return {
    title: locale?.title || '',
    description: locale?.description || '',
    button_text: locale?.button_text || '',
    success_message: locale?.success_message || '',
    locale
  }
}

export function resolveWidgetTitle(
  item: WidgetItem,
  lang: string,
  defaultLang?: string,
  fallback = ''
): string {
  const bundle = pickLocaleBundle(item.translations_json, lang, defaultLang)
  return (bundle?.title || '').trim() || fallback
}

/** 列表展示用：取默认语或任意语种的 title */
export function displayFormTitle(
  form: { translations_json?: Record<string, FormLocaleBundle>; key?: string },
  defaultLang?: string
): string {
  const bundle = pickLocaleBundle(form.translations_json, defaultLang || 'zh-CN', defaultLang)
  return bundle?.title?.trim() || form.key || ''
}

export function displayWidgetTitle(
  item: WidgetItem,
  defaultLang?: string
): string {
  return resolveWidgetTitle(item, defaultLang || 'zh-CN', defaultLang, item.id)
}

const VALID_WIDGET_TYPES: WidgetType[] = ['live_chat', 'whatsapp', 'email_form']

/** 修复被误改类型的挂件（如默认 WA 被写成 email_form） */
export function normalizeWidgetItem(item: WidgetItem): WidgetItem {
  let type: WidgetType = VALID_WIDGET_TYPES.includes(item.type) ? item.type : 'live_chat'

  if (item.id === 'wgt_default_wa') type = 'whatsapp'
  else if (item.id === 'wgt_default_email') type = 'email_form'
  else if (item.id === 'wgt_default_chat') type = 'live_chat'
  else {
    const titles = Object.values(item.translations_json || {})
      .map(b => (b?.title || '').toLowerCase())
      .join(' ')
    // 误存成邮件但残留 WA 号码/标题时纠正回来
    if (
      type === 'email_form' &&
      (Boolean(item.whatsapp_phone) || /whatsapp|whats\s*app/.test(titles))
    ) {
      type = 'whatsapp'
    }
  }

  if (type === 'whatsapp') {
    let translations = item.translations_json || {}
    // 默认 WA 被改成邮件后标题常被写成「邮件留言」——一并恢复
    if (item.id === 'wgt_default_wa') {
      const zh = translations['zh-CN']?.title || ''
      const en = translations.en?.title || ''
      if (/邮件|留言|email|message/i.test(zh) && !/whatsapp/i.test(zh)) {
        translations = {
          ...translations,
          'zh-CN': { ...(translations['zh-CN'] || { title: '' }), title: 'WhatsApp 咨询', fields: undefined }
        }
      }
      if (/邮件|留言|email|leave/i.test(en) && !/whatsapp/i.test(en)) {
        translations = {
          ...translations,
          en: { ...(translations.en || { title: '' }), title: 'WhatsApp', fields: undefined }
        }
      }
    }
    return {
      ...item,
      type,
      form_fields: undefined,
      whatsapp_phone: item.whatsapp_phone || '8613800000000',
      translations_json: translations
    }
  }
  if (type === 'email_form') {
    return {
      ...item,
      type,
      whatsapp_phone: undefined
    }
  }
  return { ...item, type, whatsapp_phone: undefined, form_fields: undefined }
}

export function normalizeWidgetItems(items: WidgetItem[]): WidgetItem[] {
  if (!Array.isArray(items)) return []
  return items.map(normalizeWidgetItem)
}

/** 确保 translations 覆盖全部已启用语种 */
export function ensureFormLocales(
  translations: Record<string, FormLocaleBundle>,
  langCodes: string[]
): Record<string, FormLocaleBundle> {
  const next = { ...translations }
  for (const code of langCodes) {
    if (!next[code]) next[code] = emptyFormLocaleBundle()
  }
  return next
}

export function ensureWidgetLocales(
  translations: Record<string, WidgetLocaleBundle>,
  langCodes: string[]
): Record<string, WidgetLocaleBundle> {
  const next = { ...translations }
  for (const code of langCodes) {
    if (!next[code]) next[code] = emptyWidgetLocaleBundle()
  }
  return next
}

/** AI 翻译用：把当前语种表单文案打成扁平 fields */
export function flattenFormLocaleForAi(bundle: FormLocaleBundle): Record<string, string> {
  const out: Record<string, string> = {
    title: bundle.title || '',
    description: bundle.description || '',
    button_text: bundle.button_text || '',
    success_message: bundle.success_message || ''
  }
  for (const [fk, fl] of Object.entries(bundle.fields || {})) {
    out[`field.${fk}.label`] = fl.label || ''
    if (fl.placeholder) out[`field.${fk}.placeholder`] = fl.placeholder
    ;(fl.options || []).forEach(opt => {
      out[`field.${fk}.option.${opt.key}`] = opt.label || ''
    })
  }
  return out
}

/** AI 结果写回 FormLocaleBundle（不写库，仅内存） */
export function applyAiToFormLocale(
  base: FormLocaleBundle,
  fields: Record<string, string>
): FormLocaleBundle {
  const next: FormLocaleBundle = {
    title: fields.title ?? base.title,
    description: fields.description ?? base.description,
    button_text: fields.button_text ?? base.button_text,
    success_message: fields.success_message ?? base.success_message,
    fields: { ...(base.fields || {}) }
  }
  const fieldKeys = new Set<string>()
  for (const k of Object.keys(fields)) {
    const m = /^field\.([^.]+)\./.exec(k)
    if (m) fieldKeys.add(m[1])
  }
  for (const fk of fieldKeys) {
    const prev = next.fields[fk] || { label: '' }
    const optionsMap = new Map((prev.options || []).map(o => [o.key, o.label]))
    for (const [k, v] of Object.entries(fields)) {
      const om = new RegExp(`^field\\.${fk.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\.option\\.(.+)$`).exec(k)
      if (om) optionsMap.set(om[1], v)
    }
    next.fields[fk] = {
      label: fields[`field.${fk}.label`] ?? prev.label,
      placeholder: fields[`field.${fk}.placeholder`] ?? prev.placeholder,
      options: Array.from(optionsMap.entries()).map(([key, label]) => ({ key, label }))
    }
  }
  return next
}

export function flattenWidgetLocaleForAi(
  bundle: WidgetLocaleBundle,
  fieldKeys: string[] = []
): Record<string, string> {
  const out: Record<string, string> = { title: bundle.title || '' }
  const fields = bundle.fields || {}
  const keys = fieldKeys.length > 0 ? fieldKeys : Object.keys(fields)
  for (const fk of keys) {
    const fl = fields[fk] || { label: '' }
    out[`field.${fk}.label`] = fl.label || ''
    if (fl.placeholder) out[`field.${fk}.placeholder`] = fl.placeholder
    ;(fl.options || []).forEach(opt => {
      out[`field.${fk}.option.${opt.key}`] = opt.label || ''
    })
  }
  return out
}

export function applyAiToWidgetLocale(
  base: WidgetLocaleBundle,
  fields: Record<string, string>
): WidgetLocaleBundle {
  const formLike = applyAiToFormLocale(
    {
      title: base.title || '',
      fields: base.fields || {}
    },
    fields
  )
  return { title: formLike.title, fields: formLike.fields }
}
