import type { MiddlewareHandler } from 'hono'
import type { Env } from '../types'
import { resolveApiLocaleFromHeaders } from './resolveApiLocale'
import { translateApiJsonBody } from './apiT'

/**
 * After handlers run, rewrite JSON msg/message fields to X-UI-Locale / Accept-Language.
 * Route code keeps English as the source of truth.
 */
export const apiLocaleMiddleware: MiddlewareHandler<{ Bindings: Env }> = async (c, next) => {
  await next()

  const contentType = c.res.headers.get('Content-Type') || ''
  if (!contentType.includes('application/json')) return

  const locale = resolveApiLocaleFromHeaders(name => c.req.header(name))
  if (locale === 'en') return

  try {
    const cloned = c.res.clone()
    const body = await cloned.json()
    const translated = translateApiJsonBody(locale, body)
    c.res = new Response(JSON.stringify(translated), {
      status: c.res.status,
      statusText: c.res.statusText,
      headers: c.res.headers
    })
  } catch {
    /* non-JSON or empty — leave as-is */
  }
}
