import type { Agent, AgentStatus } from '../types'
import { hashPassword } from '../utils/crypto'

/**
 * 确保存在默认管理员账号 (admin / admin123)
 */
export async function ensureDefaultAdmin(db: D1Database): Promise<void> {
  const countRes = await db.prepare('SELECT COUNT(*) as count FROM agents').first<{ count: number }>()
  if (countRes && countRes.count === 0) {
    const adminId = 'agent_' + crypto.randomUUID().slice(0, 8)
    const pwdHash = await hashPassword('admin123')
    await db.prepare(
      `INSERT INTO agents (id, username, password_hash, display_name, role, status, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      adminId,
      'admin',
      pwdHash,
      'Super Admin',
      'admin',
      'online',
      Date.now()
    ).run()
  }
}

/**
 * 验证客服账号密码
 */
export async function verifyAgent(db: D1Database, username: string, password: string): Promise<Agent | null> {
  await ensureDefaultAdmin(db)
  const agent = await db.prepare('SELECT * FROM agents WHERE username = ?').bind(username).first<Agent>()
  if (!agent) return null
  const inputHash = await hashPassword(password)
  if (agent.password_hash === inputHash) {
    return agent
  }
  return null
}

export async function getAgentById(db: D1Database, id: string): Promise<Agent | null> {
  return await db.prepare('SELECT * FROM agents WHERE id = ?').bind(id).first<Agent>()
}

export async function getAllAgents(db: D1Database): Promise<Omit<Agent, 'password_hash'>[]> {
  const res = await db.prepare(
    'SELECT id, username, display_name, avatar_url, role, status, created_at FROM agents ORDER BY created_at ASC'
  ).all<Omit<Agent, 'password_hash'>>()
  return res.results || []
}

export async function createAgent(
  db: D1Database,
  data: { username: string; password: string; display_name: string; role: 'admin' | 'agent' }
): Promise<string> {
  const existing = await db.prepare('SELECT id FROM agents WHERE username = ?').bind(data.username).first()
  if (existing) {
    throw new Error('Username is already taken')
  }
  const id = 'agent_' + crypto.randomUUID().slice(0, 8)
  const pwdHash = await hashPassword(data.password)
  await db.prepare(
    `INSERT INTO agents (id, username, password_hash, display_name, role, status, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    id,
    data.username,
    pwdHash,
    data.display_name,
    data.role || 'agent',
    'offline',
    Date.now()
  ).run()
  return id
}

export async function updateAgent(
  db: D1Database,
  id: string,
  data: { display_name?: string; role?: 'admin' | 'agent'; password?: string }
): Promise<void> {
  if (data.password) {
    const pwdHash = await hashPassword(data.password)
    await db.prepare('UPDATE agents SET password_hash = ? WHERE id = ?').bind(pwdHash, id).run()
  }
  if (data.display_name) {
    await db.prepare('UPDATE agents SET display_name = ? WHERE id = ?').bind(data.display_name, id).run()
  }
  if (data.role) {
    await db.prepare('UPDATE agents SET role = ? WHERE id = ?').bind(data.role, id).run()
  }
}

export async function deleteAgent(db: D1Database, id: string): Promise<void> {
  const agent = await getAgentById(db, id)
  if (!agent) throw new Error('Agent not found')
  if (agent.username === 'admin') {
    throw new Error('Cannot delete the default super admin')
  }
  await db.prepare('DELETE FROM agents WHERE id = ?').bind(id).run()
}

export async function updateCurrentProfile(
  db: D1Database,
  id: string,
  data: { username: string; display_name: string; old_password?: string; new_password?: string }
): Promise<Agent> {
  const current = await getAgentById(db, id)
  if (!current) throw new Error('Account not found')

  if (data.new_password) {
    if (!data.old_password) {
      throw new Error('Current password is required to change password')
    }
    const oldHash = await hashPassword(data.old_password)
    if (current.password_hash !== oldHash) {
      throw new Error('Current password is incorrect')
    }
    const newHash = await hashPassword(data.new_password)
    await db.prepare('UPDATE agents SET password_hash = ? WHERE id = ?').bind(newHash, id).run()
  }

  if (data.username !== current.username) {
    const conflict = await db.prepare('SELECT id FROM agents WHERE username = ? AND id != ?')
      .bind(data.username, id).first()
    if (conflict) {
      throw new Error('Username is already taken')
    }
  }

  await db.prepare('UPDATE agents SET username = ?, display_name = ? WHERE id = ?')
    .bind(data.username, data.display_name, id).run()

  return (await getAgentById(db, id))!
}

export async function updateAgentStatus(db: D1Database, id: string, status: AgentStatus): Promise<void> {
  await db.prepare('UPDATE agents SET status = ? WHERE id = ?').bind(status, id).run()
}

export async function getOnlineAgents(db: D1Database): Promise<Agent[]> {
  const res = await db.prepare("SELECT * FROM agents WHERE status != 'offline'").all<Agent>()
  return res.results || []
}

/**
 * 智能负载均衡算法：选择当前接待活跃客户数最少的在线坐席
 */
export async function findLeastLoadedOnlineAgent(
  db: D1Database
): Promise<{ id: string; name: string; username: string } | null> {
  await ensureDefaultAdmin(db)
  let candidates = await db.prepare(
    "SELECT id, username, display_name FROM agents WHERE status = 'online'"
  ).all<{ id: string; username: string; display_name: string }>()
  let list = candidates.results || []

  // 若无在线坐席，退而求其次选择管理员兜底
  if (list.length === 0) {
    const adminRes = await db.prepare(
      "SELECT id, username, display_name FROM agents WHERE role = 'admin' LIMIT 1"
    ).all<{ id: string; username: string; display_name: string }>()
    list = adminRes.results || []
  }

  if (list.length === 0) return null
  if (list.length === 1) return { id: list[0].id, name: list[0].display_name, username: list[0].username }

  // 统计各坐席当前名下的活跃客户数
  const loadRes = await db.prepare(
    "SELECT assigned_agent_id, COUNT(*) as active_count FROM conversations WHERE status = 'active' AND assigned_agent_id IS NOT NULL GROUP BY assigned_agent_id"
  ).all<{ assigned_agent_id: string; active_count: number }>()

  const loadMap = new Map<string, number>()
  for (const r of loadRes.results || []) {
    loadMap.set(r.assigned_agent_id, r.active_count)
  }

  list.sort((a, b) => (loadMap.get(a.id) || 0) - (loadMap.get(b.id) || 0))
  return { id: list[0].id, name: list[0].display_name, username: list[0].username }
}
