import { Hono } from 'hono'
import type { Env } from '../types'
import { getSystemSetting } from '../db/settings'
import { getOrCreateWhatsAppConversation, insertWhatsAppMessage } from '../db/conversations'
import { listSites } from '../db/sites'

export const webhookRouter = new Hono<{ Bindings: Env }>()

/**
 * Meta for Developers WhatsApp Cloud API Webhook 验证握手端点
 * Meta 在开发者配置 Webhook 时会向此 GET 接口发送验证请求
 */
webhookRouter.get('/webhook/whatsapp', async (c) => {
  const mode = c.req.query('hub.mode')
  const token = c.req.query('hub.verify_token')
  const challenge = c.req.query('hub.challenge')

  // 从数据库系统设置中获取配置的 verify_token，默认兜底为 meta_im_secret
  const configuredToken = (await getSystemSetting(c.env.DB, 'whatsapp_verify_token')) || 'meta_im_secret'

  if (mode === 'subscribe' && token === configuredToken) {
    console.log('[Meta Webhook] WhatsApp webhook verified')
    return new Response(challenge, { status: 200 })
  }

  return c.text('Forbidden: Invalid verify token', 403)
})

/**
 * Meta WhatsApp Cloud API 消息接收推送端点
 * 当客户向企业的 WhatsApp Business 号码发消息时，Meta 实时推送事件到此接口
 */
webhookRouter.post('/webhook/whatsapp', async (c) => {
  try {
    const body = await c.req.json() as any

    // 校验是否为 WhatsApp 消息推送数据结构
    if (body.object !== 'whatsapp_business_account') {
      return c.json({ status: 'ignored' }, 200)
    }

    const entries = body.entry || []
    for (const entry of entries) {
      const changes = entry.changes || []
      for (const change of changes) {
        if (change.field !== 'messages') continue

        const value = change.value || {}
        const messages = value.messages || []
        const contacts = value.contacts || []

        for (const msg of messages) {
          const waId = msg.from
          const contactInfo = contacts.find((ct: any) => ct.wa_id === waId)
          const senderName = contactInfo?.profile?.name || `WhatsApp (+${waId})`

          let content = ''
          if (msg.type === 'text') {
            content = msg.text?.body || ''
          } else if (msg.type === 'image') {
            content = msg.image?.caption ? `[Image] ${msg.image.caption}` : '[Image]'
          } else if (msg.type === 'video') {
            content = '[Video]'
          } else if (msg.type === 'audio') {
            content = '[Voice]'
          } else if (msg.type === 'document') {
            content = `[File] ${msg.document?.filename || ''}`
          } else {
            content = `[${msg.type || 'unknown'} message]`
          }

          if (!content) continue

          // WhatsApp 暂归属第一个启用站点（后期可做渠道↔站点映射）
          const sites = await listSites(c.env.DB)
          const waSite = sites.find(s => s.status === 'active')
          if (!waSite) {
            console.warn('[Meta Webhook] no active site; drop WhatsApp message')
            continue
          }
          const conv = await getOrCreateWhatsAppConversation(
            c.env.DB,
            waId,
            senderName,
            waSite.id
          )
          await insertWhatsAppMessage(c.env.DB, conv.id, waId, senderName, content)

          console.log(`[Meta Webhook] WhatsApp (+${waId}): ${content}`)
        }
      }
    }

    return c.json({ status: 'success' }, 200)
  } catch (err: any) {
    console.error('[Meta Webhook] push handler error:', err)
    // 即使处理有小错误，也向 Meta 响应 200，避免 Meta 错误重试拥堵 Webhook
    return c.json({ status: 'error', message: err.message }, 200)
  }
})
