import { Hono } from 'hono'
import type { Context } from 'hono'
import type { Env } from '../types'
import { isErrorResponse, requireAdmin, requireAgent } from '../middleware/auth'
import { getInquiryFunnelStats } from '../db/inquiryStats'
import { getSystemSetting, updateSystemSettings } from '../db/settings'
import {
  agentCanAccessSite,
  getMergedSiteSettings,
  updateSiteSettings
} from '../db/sites'
import {
  GA_REFRESH_KEY,
  buildGaAuthUrl,
  disconnectGa,
  exchangeGaCode,
  gaOAuthConfigured,
  listGaProperties,
  resolveGaOAuthCreds,
  runGaReport
} from '../services/gaService'

export const analyticsRouter = new Hono<{ Bindings: Env }>()

function readSiteId(c: Context<{ Bindings: Env }>, body?: Record<string, unknown>): string {
  return (
    (c.req.query('site_id') || '').trim() ||
    (c.req.header('X-Site-Id') || '').trim() ||
    (typeof body?.site_id === 'string' ? body.site_id.trim() : '')
  )
}

/** 本系统询盘漏斗（第一方，可按站点筛选） */
analyticsRouter.get('/analytics/inquiry-funnel', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const days = Number(c.req.query('days') || '7')
    const siteId = (c.req.query('site_id') || c.req.query('site') || '').trim()
    const data = await getInquiryFunnelStats(c.env.DB, days, siteId || undefined)
    return c.json({ success: true, data })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

analyticsRouter.get('/analytics/ga/status', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const siteId = readSiteId(c)
    if (siteId && !(await agentCanAccessSite(c.env.DB, agent, siteId))) {
      return c.json({ success: false, message: 'No permission to access this site' }, 403)
    }
    const refresh = await getSystemSetting(c.env.DB, GA_REFRESH_KEY)
    const email = (await getSystemSetting(c.env.DB, 'ga_connected_email')) || ''
    const oauthOk = await gaOAuthConfigured(c.env, c.env.DB)
    // Measurement / Property / 开关按站点；OAuth 连接状态全局
    let propertyId = ''
    let reportEnabled = false
    let eventEnabled = false
    let measurementId = ''
    if (siteId) {
      const siteMap = await getMergedSiteSettings(c.env.DB, siteId)
      propertyId = siteMap.ga_property_id || ''
      reportEnabled = siteMap.ga_report_enabled === '1'
      eventEnabled = siteMap.ga_enabled === '1'
      measurementId = siteMap.ga_measurement_id || ''
    }
    return c.json({
      success: true,
      data: {
        oauth_configured: oauthOk,
        connected: Boolean(refresh),
        email,
        site_id: siteId || '',
        property_id: propertyId,
        report_enabled: reportEnabled,
        event_enabled: eventEnabled,
        measurement_id: measurementId
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

analyticsRouter.get('/analytics/ga/oauth/start', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const creds = await resolveGaOAuthCreds(c.env, c.env.DB)
    if (!creds.clientId || !creds.clientSecret) {
      return c.json(
        {
          success: false,
          message:
            'Enter Google Client ID and Client secret on this page and save, then connect (or set Cloudflare Secrets)'
        },
        400
      )
    }
    const origin = new URL(c.req.url).origin
    const redirectUri =
      (c.env.GA_OAUTH_REDIRECT_URI || '').trim() ||
      `${origin}/api/analytics/ga/oauth/callback`
    const state = crypto.randomUUID().slice(0, 16)
    await updateSystemSettings(c.env.DB, { ga_oauth_state: state })
    const url = buildGaAuthUrl(creds, redirectUri, state)
    return c.json({ success: true, data: { url, redirect_uri: redirectUri } })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

analyticsRouter.get('/analytics/ga/oauth/callback', async (c) => {
  const origin = new URL(c.req.url).origin
  const adminPathSecret = (c.env.ADMIN_PATH_SECRET || '').trim()
  const adminBase = adminPathSecret ? `${origin}/admin-${adminPathSecret}` : origin

  try {
    const err = c.req.query('error')
    if (err) {
      return c.redirect(`${adminBase}?ga=error&msg=${encodeURIComponent(err)}`)
    }
    const code = c.req.query('code') || ''
    const state = c.req.query('state') || ''
    const expected = (await getSystemSetting(c.env.DB, 'ga_oauth_state')) || ''
    if (!code || !state || state !== expected) {
      return c.redirect(`${adminBase}?ga=error&msg=${encodeURIComponent('Invalid OAuth state')}`)
    }
    const creds = await resolveGaOAuthCreds(c.env, c.env.DB)
    if (!creds.clientId || !creds.clientSecret) {
      return c.redirect(
        `${adminBase}?ga=error&msg=${encodeURIComponent('Google Client ID/secret is not configured')}`
      )
    }

    const redirectUri =
      (c.env.GA_OAUTH_REDIRECT_URI || '').trim() ||
      `${origin}/api/analytics/ga/oauth/callback`

    const tokens = await exchangeGaCode(creds, code, redirectUri)
    const updates: Record<string, string> = {
      ga_oauth_state: '',
      ga_connected_email: tokens.email || '',
      ga_report_enabled: '1'
    }
    if (tokens.refresh_token) {
      updates[GA_REFRESH_KEY] = tokens.refresh_token
    } else {
      const existing = await getSystemSetting(c.env.DB, GA_REFRESH_KEY)
      if (!existing) {
        return c.redirect(
          `${adminBase}?ga=error&msg=${encodeURIComponent('No refresh_token received. Revoke app access and try again')}`
        )
      }
    }
    await updateSystemSettings(c.env.DB, updates)
    return c.redirect(`${adminBase}?ga=connected#inquiry_analytics`)
  } catch (e: any) {
    return c.redirect(
      `${adminBase}?ga=error&msg=${encodeURIComponent(e.message || 'Connection failed')}`
    )
  }
})

analyticsRouter.post('/analytics/ga/disconnect', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    await disconnectGa(c.env.DB)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

analyticsRouter.get('/analytics/ga/properties', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    if (!(await gaOAuthConfigured(c.env, c.env.DB))) {
      return c.json({ success: false, message: 'Save Google Client ID and secret first' }, 400)
    }
    const list = await listGaProperties(c.env, c.env.DB)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

analyticsRouter.post('/analytics/ga/property', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    const siteId = readSiteId(c, body)
    if (!siteId) {
      return c.json({ success: false, message: 'Select a site before linking a GA4 property' }, 400)
    }
    if (!(await agentCanAccessSite(c.env.DB, admin, siteId))) {
      return c.json({ success: false, message: 'No permission to manage this site' }, 403)
    }
    const id = String(body.property_id || '')
      .replace(/^properties\//, '')
      .trim()
    if (!id) return c.json({ success: false, message: 'Select a GA4 property' }, 400)
    const updates: Record<string, string> = { ga_property_id: id }
    if (body.report_enabled !== undefined) {
      updates.ga_report_enabled = body.report_enabled ? '1' : '0'
    } else {
      updates.ga_report_enabled = '1'
    }
    await updateSiteSettings(c.env.DB, siteId, updates)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

analyticsRouter.get('/analytics/ga/report', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent

    const siteId = readSiteId(c)
    if (!siteId) {
      return c.json({ success: false, message: 'Select a site before viewing GA reports' }, 400)
    }
    if (!(await agentCanAccessSite(c.env.DB, agent, siteId))) {
      return c.json({ success: false, message: 'No permission to access this site' }, 403)
    }

    const siteMap = await getMergedSiteSettings(c.env.DB, siteId)
    if (siteMap.ga_report_enabled !== '1') {
      return c.json({ success: false, message: 'GA reporting disabled for this site' }, 400)
    }
    const propertyId = siteMap.ga_property_id || ''
    if (!propertyId) {
      return c.json({ success: false, message: 'Select a GA4 property for this site first' }, 400)
    }

    const kind = (c.req.query('kind') || 'overview') as 'overview' | 'sources' | 'pages'
    if (!['overview', 'sources', 'pages'].includes(kind)) {
      return c.json({ success: false, message: 'Invalid report type' }, 400)
    }
    const days = Number(c.req.query('days') || '7')
    const site = (c.req.query('site') || '').trim().toLowerCase().replace(/^www\./, '')

    const cacheKey = new Request(
      `https://ga-cache.internal/${siteId}/${propertyId}/${kind}/${days}/${site || 'all'}`
    )
    try {
      const hit = await caches.default.match(cacheKey)
      if (hit) {
        const cached = await hit.json()
        return c.json({ success: true, data: cached, cached: true })
      }
    } catch {
      /* ignore */
    }

    const raw = await runGaReport(c.env, c.env.DB, {
      propertyId,
      rangeDays: days,
      kind,
      hostName: site || undefined
    })

    let data: unknown
    if (kind === 'overview') {
      const metrics = raw.metricHeaders || []
      const values = raw.rows?.[0]?.metricValues || []
      const map: Record<string, number> = {}
      metrics.forEach((m: any, i: number) => {
        map[m.name] = Number(values[i]?.value || 0)
      })
      data = {
        kind,
        days,
        site: site || '',
        activeUsers: map.activeUsers || 0,
        sessions: map.sessions || 0,
        screenPageViews: map.screenPageViews || 0,
        eventCount: map.eventCount || 0,
        quota: raw.propertyQuota || null
      }
    } else {
      const rows = (raw.rows || []).map((r: any) => ({
        name: r.dimensionValues?.[0]?.value || '',
        sessions: Number(r.metricValues?.[0]?.value || 0),
        activeUsers: Number(r.metricValues?.[1]?.value || 0)
      }))
      data = { kind, days, site: site || '', rows, quota: raw.propertyQuota || null }
    }

    try {
      await caches.default.put(
        cacheKey,
        new Response(JSON.stringify(data), {
          headers: {
            'Content-Type': 'application/json',
            'Cache-Control': 'max-age=600'
          }
        })
      )
    } catch {
      /* ignore */
    }

    return c.json({ success: true, data, cached: false })
  } catch (err: any) {
    const status = err.status === 429 ? 429 : 500
    return c.json({ success: false, message: err.message || 'GA report failed' }, status)
  }
})
