/**
 * 第一方询盘漏斗：按 site_id 隔离（不再靠 hostname 猜测）
 */

import { ensureSitesSchema, listSites } from './sites'

export type InquiryFunnelStats = {
  range_days: number
  from_ms: number
  to_ms: number
  /** 当前筛选站点 id；空=全部站点合计 */
  site_id: string
  sites: Array<{ id: string; name: string; conversations: number }>
  conversations: number
  engaged_conversations: number
  visitor_messages: number
  inquiry_tickets: number
  form_submissions: number
  crm_new: number
  engage_rate: number
  inquiry_rate: number
  top_utm: Array<{ source: string; conversations: number }>
  top_landing: Array<{ path: string; conversations: number }>
}

function daysToRange(days: number): { from: number; to: number } {
  const to = Date.now()
  const d = Math.min(90, Math.max(1, Math.floor(days) || 7))
  return { from: to - d * 24 * 60 * 60 * 1000, to }
}

export async function getInquiryFunnelStats(
  db: D1Database,
  rangeDays = 7,
  siteIdFilter?: string
): Promise<InquiryFunnelStats> {
  await ensureSitesSchema(db)
  const { from, to } = daysToRange(rangeDays)
  const siteId = (siteIdFilter || '').trim()

  const recent = await db
    .prepare(
      `SELECT id, site_id, page_context FROM conversations
       WHERE created_at >= ? AND created_at <= ?
       ORDER BY created_at DESC LIMIT 2000`
    )
    .bind(from, to)
    .all<{ id: string; site_id: string | null; page_context: string | null }>()

  const rows = recent.results || []
  const siteCount = new Map<string, number>()
  const matchedIds: string[] = []
  const matchedContexts: Array<{ utm_source?: string; url?: string }> = []

  for (const row of rows) {
    const sid = row.site_id || ''
    if (sid) siteCount.set(sid, (siteCount.get(sid) || 0) + 1)
    if (!siteId || sid === siteId) {
      matchedIds.push(row.id)
      if (row.page_context) {
        try {
          matchedContexts.push(JSON.parse(row.page_context))
        } catch {
          matchedContexts.push({})
        }
      } else {
        matchedContexts.push({})
      }
    }
  }

  const allSites = await listSites(db)
  const sites = allSites
    .map(s => ({
      id: s.id,
      name: s.name,
      conversations: siteCount.get(s.id) || 0
    }))
    .sort((a, b) => b.conversations - a.conversations)

  let conversations = 0
  let engaged = 0
  let visitorMessages = 0
  let tickets = 0
  let formSubmissions = 0
  let crmNew = 0

  if (!siteId) {
    const convRow = await db
      .prepare('SELECT COUNT(*) as c FROM conversations WHERE created_at >= ? AND created_at <= ?')
      .bind(from, to)
      .first<{ c: number }>()
    conversations = convRow?.c || 0

    const engagedRow = await db
      .prepare(
        `SELECT COUNT(DISTINCT conversation_id) as c FROM messages
         WHERE sender_type = 'visitor' AND created_at >= ? AND created_at <= ?`
      )
      .bind(from, to)
      .first<{ c: number }>()
    engaged = engagedRow?.c || 0

    const visitorMsgRow = await db
      .prepare(
        `SELECT COUNT(*) as c FROM messages
         WHERE sender_type = 'visitor' AND created_at >= ? AND created_at <= ?`
      )
      .bind(from, to)
      .first<{ c: number }>()
    visitorMessages = visitorMsgRow?.c || 0

    const ticketRow = await db
      .prepare(
        `SELECT COUNT(*) as c FROM messages
         WHERE sender_type = 'visitor'
           AND created_at >= ? AND created_at <= ?
           AND (content LIKE '[Email inquiry]%' OR content LIKE '【邮件留言】%')`
      )
      .bind(from, to)
      .first<{ c: number }>()
    tickets = ticketRow?.c || 0

    try {
      const formRow = await db
        .prepare(
          'SELECT COUNT(*) as c FROM form_submissions WHERE created_at >= ? AND created_at <= ?'
        )
        .bind(from, to)
        .first<{ c: number }>()
      formSubmissions = formRow?.c || 0
    } catch {
      formSubmissions = 0
    }

    try {
      const crmRow = await db
        .prepare(
          'SELECT COUNT(*) as c FROM crm_customers WHERE created_at >= ? AND created_at <= ?'
        )
        .bind(from, to)
        .first<{ c: number }>()
      crmNew = crmRow?.c || 0
    } catch {
      crmNew = 0
    }
  } else {
    conversations = matchedIds.length
    if (matchedIds.length > 0) {
      const batchSize = 80
      for (let i = 0; i < matchedIds.length; i += batchSize) {
        const batch = matchedIds.slice(i, i + batchSize)
        const ph = batch.map(() => '?').join(',')
        const eng = await db
          .prepare(
            `SELECT COUNT(DISTINCT conversation_id) as c FROM messages
             WHERE sender_type = 'visitor' AND conversation_id IN (${ph})
               AND created_at >= ? AND created_at <= ?`
          )
          .bind(...batch, from, to)
          .first<{ c: number }>()
        engaged += eng?.c || 0

        const vm = await db
          .prepare(
            `SELECT COUNT(*) as c FROM messages
             WHERE sender_type = 'visitor' AND conversation_id IN (${ph})
               AND created_at >= ? AND created_at <= ?`
          )
          .bind(...batch, from, to)
          .first<{ c: number }>()
        visitorMessages += vm?.c || 0

        const tk = await db
          .prepare(
            `SELECT COUNT(*) as c FROM messages
             WHERE sender_type = 'visitor' AND conversation_id IN (${ph})
               AND created_at >= ? AND created_at <= ?
               AND (content LIKE '[Email inquiry]%' OR content LIKE '【邮件留言】%')`
          )
          .bind(...batch, from, to)
          .first<{ c: number }>()
        tickets += tk?.c || 0
      }
    }

    try {
      const formRow = await db
        .prepare(
          `SELECT COUNT(*) as c FROM form_submissions
           WHERE site_id = ? AND created_at >= ? AND created_at <= ?`
        )
        .bind(siteId, from, to)
        .first<{ c: number }>()
      formSubmissions = formRow?.c || 0
    } catch {
      formSubmissions = 0
    }
    crmNew = 0
  }

  const utmMap = new Map<string, number>()
  const landMap = new Map<string, number>()
  for (const pc of matchedContexts) {
    const src = (pc.utm_source || '').trim() || '(direct)'
    utmMap.set(src, (utmMap.get(src) || 0) + 1)
    if (pc.url) {
      try {
        const path = new URL(pc.url).pathname || '/'
        landMap.set(path, (landMap.get(path) || 0) + 1)
      } catch {
        /* ignore */
      }
    }
  }

  const inquiries = tickets + formSubmissions

  return {
    range_days: Math.min(90, Math.max(1, Math.floor(rangeDays) || 7)),
    from_ms: from,
    to_ms: to,
    site_id: siteId,
    sites,
    conversations,
    engaged_conversations: engaged,
    visitor_messages: visitorMessages,
    inquiry_tickets: tickets,
    form_submissions: formSubmissions,
    crm_new: crmNew,
    engage_rate: conversations > 0 ? engaged / conversations : 0,
    inquiry_rate: conversations > 0 ? inquiries / conversations : 0,
    top_utm: [...utmMap.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([source, conversations]) => ({ source, conversations })),
    top_landing: [...landMap.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8)
      .map(([path, conversations]) => ({ path, conversations }))
  }
}
