import type { Env } from '../types'

const AGENT_TTL_MS = 7 * 24 * 60 * 60 * 1000
const VISITOR_TTL_MS = 30 * 24 * 60 * 60 * 1000

export type AgentTokenPayload = {
  t: 'a'
  id: string
  role: 'admin' | 'agent'
  exp: number
}

export type VisitorTokenPayload = {
  t: 'v'
  vid: string
  cid: string
  exp: number
}

function sessionSecret(env: Env): string {
  return (
    (env as any).SESSION_SECRET ||
    env.ADMIN_SECURITY_CODE ||
    env.ADMIN_PATH_SECRET ||
    'cf-im-dev-session-secret'
  )
}

function b64url(bytes: ArrayBuffer | Uint8Array): string {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes)
  let s = ''
  for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i])
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '')
}

function b64urlJson(obj: unknown): string {
  return b64url(new TextEncoder().encode(JSON.stringify(obj)))
}

function fromB64url(s: string): Uint8Array {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4))
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + pad
  const bin = atob(b64)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

async function hmacKey(env: Env): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(sessionSecret(env)),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify']
  )
}

async function sign(env: Env, payloadB64: string): Promise<string> {
  const key = await hmacKey(env)
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(payloadB64))
  return b64url(sig)
}

async function verifySig(env: Env, payloadB64: string, sigB64: string): Promise<boolean> {
  const key = await hmacKey(env)
  return crypto.subtle.verify('HMAC', key, fromB64url(sigB64), new TextEncoder().encode(payloadB64))
}

export async function issueAgentToken(
  env: Env,
  agent: { id: string; role: 'admin' | 'agent' }
): Promise<string> {
  const payload: AgentTokenPayload = {
    t: 'a',
    id: agent.id,
    role: agent.role,
    exp: Date.now() + AGENT_TTL_MS
  }
  const body = b64urlJson(payload)
  const sig = await sign(env, body)
  return `${body}.${sig}`
}

export async function issueVisitorToken(
  env: Env,
  visitorId: string,
  conversationId: string
): Promise<string> {
  const payload: VisitorTokenPayload = {
    t: 'v',
    vid: visitorId,
    cid: conversationId,
    exp: Date.now() + VISITOR_TTL_MS
  }
  const body = b64urlJson(payload)
  const sig = await sign(env, body)
  return `${body}.${sig}`
}

export async function verifyAgentToken(
  env: Env,
  token: string
): Promise<AgentTokenPayload | null> {
  const parts = token.split('.')
  if (parts.length !== 2) return null
  const [body, sig] = parts
  if (!(await verifySig(env, body, sig))) return null
  try {
    const payload = JSON.parse(new TextDecoder().decode(fromB64url(body))) as AgentTokenPayload
    if (payload.t !== 'a' || !payload.id || !payload.exp || payload.exp < Date.now()) return null
    return payload
  } catch {
    return null
  }
}

export async function verifyVisitorToken(
  env: Env,
  token: string,
  visitorId: string,
  conversationId: string
): Promise<boolean> {
  const parts = token.split('.')
  if (parts.length !== 2) return false
  const [body, sig] = parts
  if (!(await verifySig(env, body, sig))) return false
  try {
    const payload = JSON.parse(new TextDecoder().decode(fromB64url(body))) as VisitorTokenPayload
    return (
      payload.t === 'v' &&
      payload.vid === visitorId &&
      payload.cid === conversationId &&
      !!payload.exp &&
      payload.exp >= Date.now()
    )
  } catch {
    return false
  }
}

/** Worker → DO 内部调用校验 */
export function internalRequestHeaders(env: Env): Record<string, string> {
  return {
    'Content-Type': 'application/json',
    'X-Internal-Secret': sessionSecret(env)
  }
}

export function assertInternalRequest(env: Env, req: Request): boolean {
  const got = req.headers.get('X-Internal-Secret') || ''
  return !!got && got === sessionSecret(env)
}
