/**
 * Google Analytics：OAuth 刷新 + Data API / Admin API 按需调用（方案 B，默认不落库）
 * 客户端 ID/密钥优先读后台设置，其次读环境变量 Secrets
 */
import type { Env } from '../types'
import { getSystemSetting, updateSystemSettings } from '../db/settings'

export const GA_REFRESH_KEY = 'ga_oauth_refresh_token'
const GA_ACCESS_CACHE_KEY = 'ga_oauth_access_cache'
export const GA_CLIENT_ID_KEY = 'ga_oauth_client_id'
export const GA_CLIENT_SECRET_KEY = 'ga_oauth_client_secret'

export type GaOAuthCreds = { clientId: string; clientSecret: string }

/** 后台设置优先，环境变量兜底 */
export async function resolveGaOAuthCreds(env: Env, db: D1Database): Promise<GaOAuthCreds> {
  const fromDbId = ((await getSystemSetting(db, GA_CLIENT_ID_KEY)) || '').trim()
  const fromDbSecret = ((await getSystemSetting(db, GA_CLIENT_SECRET_KEY)) || '').trim()
  const clientId = fromDbId || (env.GA_OAUTH_CLIENT_ID || '').trim()
  const clientSecret = fromDbSecret || (env.GA_OAUTH_CLIENT_SECRET || '').trim()
  return { clientId, clientSecret }
}

export async function gaOAuthConfigured(env: Env, db: D1Database): Promise<boolean> {
  const c = await resolveGaOAuthCreds(env, db)
  return Boolean(c.clientId && c.clientSecret)
}

export function buildGaAuthUrl(creds: GaOAuthCreds, redirectUri: string, state: string): string {
  const params = new URLSearchParams({
    client_id: creds.clientId,
    redirect_uri: redirectUri,
    response_type: 'code',
    access_type: 'offline',
    prompt: 'consent',
    scope: [
      'https://www.googleapis.com/auth/analytics.readonly',
      'openid',
      'email'
    ].join(' '),
    state
  })
  return `https://accounts.google.com/o/oauth2/v2/auth?${params}`
}

export async function exchangeGaCode(
  creds: GaOAuthCreds,
  code: string,
  redirectUri: string
): Promise<{ refresh_token?: string; access_token: string; expires_in: number; email?: string }> {
  const body = new URLSearchParams({
    code,
    client_id: creds.clientId,
    client_secret: creds.clientSecret,
    redirect_uri: redirectUri,
    grant_type: 'authorization_code'
  })
  const res = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body
  })
  const json = (await res.json()) as any
  if (!res.ok) {
    throw new Error(json.error_description || json.error || 'OAuth token exchange failed')
  }

  let email = ''
  if (json.access_token) {
    try {
      const ui = await fetch('https://www.googleapis.com/oauth2/v2/userinfo', {
        headers: { Authorization: `Bearer ${json.access_token}` }
      })
      const u = (await ui.json()) as { email?: string }
      email = u.email || ''
    } catch {
      /* ignore */
    }
  }

  return {
    refresh_token: json.refresh_token,
    access_token: json.access_token,
    expires_in: Number(json.expires_in) || 3600,
    email
  }
}

async function refreshAccessToken(env: Env, db: D1Database): Promise<string> {
  const refresh = await getSystemSetting(db, GA_REFRESH_KEY)
  if (!refresh) throw new Error('Google account not connected')

  const cachedRaw = await getSystemSetting(db, GA_ACCESS_CACHE_KEY)
  if (cachedRaw) {
    try {
      const cached = JSON.parse(cachedRaw) as { access_token?: string; exp?: number }
      if (cached.access_token && cached.exp && cached.exp > Date.now() + 60_000) {
        return cached.access_token
      }
    } catch {
      /* ignore */
    }
  }

  const creds = await resolveGaOAuthCreds(env, db)
  if (!creds.clientId || !creds.clientSecret) {
    throw new Error('Enter Client ID and Client secret in Google Analytics settings first')
  }

  const body = new URLSearchParams({
    client_id: creds.clientId,
    client_secret: creds.clientSecret,
    refresh_token: refresh,
    grant_type: 'refresh_token'
  })
  const res = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body
  })
  const json = (await res.json()) as any
  if (!res.ok) {
    throw new Error(json.error_description || json.error || 'Failed to refresh Google token. Please reconnect')
  }
  const access = json.access_token as string
  const exp = Date.now() + (Number(json.expires_in) || 3600) * 1000
  await updateSystemSettings(db, {
    [GA_ACCESS_CACHE_KEY]: JSON.stringify({ access_token: access, exp })
  })
  return access
}

export async function disconnectGa(db: D1Database): Promise<void> {
  await updateSystemSettings(db, {
    [GA_REFRESH_KEY]: '',
    [GA_ACCESS_CACHE_KEY]: '',
    ga_connected_email: '',
    ga_property_id: '',
    ga_report_enabled: '0'
  })
}

export async function listGaProperties(env: Env, db: D1Database) {
  const token = await refreshAccessToken(env, db)
  const res = await fetch(
    'https://analyticsadmin.googleapis.com/v1beta/accountSummaries?pageSize=200',
    { headers: { Authorization: `Bearer ${token}` } }
  )
  const json = (await res.json()) as any
  if (!res.ok) {
    throw new Error(json.error?.message || 'Failed to list GA properties')
  }
  const list: Array<{ property_id: string; display_name: string; account: string }> = []
  for (const acc of json.accountSummaries || []) {
    for (const p of acc.propertySummaries || []) {
      const name = String(p.property || '')
      const id = name.replace(/^properties\//, '')
      if (!id) continue
      list.push({
        property_id: id,
        display_name: p.displayName || id,
        account: acc.displayName || acc.account || ''
      })
    }
  }
  return list
}

function propertyResource(propertyId: string): string {
  const id = propertyId.replace(/^properties\//, '').trim()
  return `properties/${id}`
}

export async function runGaReport(
  env: Env,
  db: D1Database,
  opts: {
    propertyId: string
    rangeDays: number
    kind: 'overview' | 'sources' | 'pages'
    /** 按主机名筛选（多站同一 Property 时） */
    hostName?: string
  }
) {
  const token = await refreshAccessToken(env, db)
  const days = Math.min(90, Math.max(1, opts.rangeDays || 7))
  const dateRanges = [{ startDate: `${days}daysAgo`, endDate: 'yesterday' }]
  const host = (opts.hostName || '').trim().toLowerCase().replace(/^www\./, '')

  const dimensionFilter = host
    ? {
        filter: {
          fieldName: 'hostName',
          stringFilter: {
            matchType: 'CONTAINS',
            value: host,
            caseSensitive: false
          }
        }
      }
    : undefined

  let body: Record<string, unknown>
  if (opts.kind === 'overview') {
    body = {
      dateRanges,
      metrics: [
        { name: 'activeUsers' },
        { name: 'sessions' },
        { name: 'screenPageViews' },
        { name: 'eventCount' }
      ],
      ...(dimensionFilter ? { dimensionFilter } : {}),
      returnPropertyQuota: true
    }
  } else if (opts.kind === 'sources') {
    body = {
      dateRanges,
      dimensions: [{ name: 'sessionDefaultChannelGroup' }],
      metrics: [{ name: 'sessions' }, { name: 'activeUsers' }],
      orderBys: [{ metric: { metricName: 'sessions' }, desc: true }],
      limit: 10,
      ...(dimensionFilter ? { dimensionFilter } : {}),
      returnPropertyQuota: true
    }
  } else {
    body = {
      dateRanges,
      dimensions: [{ name: 'landingPagePlusQueryString' }],
      metrics: [{ name: 'sessions' }, { name: 'activeUsers' }],
      orderBys: [{ metric: { metricName: 'sessions' }, desc: true }],
      limit: 10,
      ...(dimensionFilter ? { dimensionFilter } : {}),
      returnPropertyQuota: true
    }
  }

  const res = await fetch(
    `https://analyticsdata.googleapis.com/v1beta/${propertyResource(opts.propertyId)}:runReport`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(body)
    }
  )
  const json = (await res.json()) as any
  if (!res.ok) {
    const msg = json.error?.message || 'GA report request failed'
    const err = new Error(msg) as Error & { status?: number }
    err.status = res.status
    throw err
  }
  return json
}
