import { Hono } from 'hono'
import type { Env } from '../types'
import {
  createPrivateChat,
  verifyPrivateChatPassword,
  getPrivateChats,
  deletePrivateChat
} from '../db/privateChat'
import { getMessagesByConversation } from '../db/messages'
import { isErrorResponse, requireAgent } from '../middleware/auth'
import { clientIp, enforceRateLimit } from '../utils/rateLimit'

export const privateChatRouter = new Hono<{ Bindings: Env }>()

/** 仅当 Cloudflare 控制台手工配置了 PRIVATE_CHAT_DEVELOPER_KEY 时开启（部署工具绝不下发该值） */
function privateChatEnabled(env: Env): boolean {
  return Boolean((env.PRIVATE_CHAT_DEVELOPER_KEY || '').trim())
}

privateChatRouter.get('/private-chats/feature-status', async (c) => {
  return c.json({ success: true, enabled: privateChatEnabled(c.env) })
})

privateChatRouter.get('/private-chats', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    if (!privateChatEnabled(c.env)) {
      return c.json({ success: false, message: 'Private chat feature is disabled' }, 404)
    }
    const list = await getPrivateChats(c.env.DB)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

privateChatRouter.post('/private-chats', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const body = await c.req.json()
    const { title, password, expires_hours } = body
    if (!title || !password) {
      return c.json({ success: false, message: 'Private chat title and password are required' }, 400)
    }

    const item = await createPrivateChat(c.env.DB, title, password, agent.id, expires_hours)
    return c.json({ success: true, data: item })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

privateChatRouter.delete('/private-chats/:id', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    await deletePrivateChat(c.env.DB, id, c.env.MEDIA_BUCKET)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

privateChatRouter.post('/private-chat/verify', async (c) => {
  try {
    const rl = await enforceRateLimit({
      key: `pchat-verify:${clientIp(c)}`,
      limit: 20,
      windowSec: 300
    })
    if (!rl.ok) {
      return c.json({ success: false, message: 'Too many attempts. Please try again later' }, 429)
    }

    const { id, password } = await c.req.json()
    if (!id || !password) {
      return c.json({ success: false, message: 'Enter the access password' }, 400)
    }

    const res = await verifyPrivateChatPassword(c.env.DB, id, password)
    if (!res.success || !res.chat) {
      return c.json({ success: false, message: res.message || 'Password verification failed' }, 401)
    }

    const messages = await getMessagesByConversation(c.env.DB, id, 50)

    return c.json({
      success: true,
      data: {
        chat: res.chat,
        messages
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
