/** 概览统计：可按 site_id 限定会话范围；坐席在线数为全局 */
export async function getDashboardStats(db: D1Database, siteId?: string) {
  const site = (siteId || '').trim()
  const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000

  let totalConversations = 0
  let todayConversations = 0
  let totalMessages = 0

  if (site) {
    const totalConvs = await db
      .prepare('SELECT COUNT(*) as c FROM conversations WHERE site_id = ?')
      .bind(site)
      .first<{ c: number }>()
    totalConversations = totalConvs?.c || 0

    const recentConvs = await db
      .prepare('SELECT COUNT(*) as c FROM conversations WHERE site_id = ? AND created_at > ?')
      .bind(site, oneDayAgo)
      .first<{ c: number }>()
    todayConversations = recentConvs?.c || 0

    const msgRow = await db
      .prepare(
        `SELECT COUNT(*) as c FROM messages m
         INNER JOIN conversations c ON c.id = m.conversation_id
         WHERE c.site_id = ?`
      )
      .bind(site)
      .first<{ c: number }>()
    totalMessages = msgRow?.c || 0
  } else {
    const totalConvs = await db
      .prepare('SELECT COUNT(*) as c FROM conversations')
      .first<{ c: number }>()
    totalConversations = totalConvs?.c || 0

    const recentConvs = await db
      .prepare('SELECT COUNT(*) as c FROM conversations WHERE created_at > ?')
      .bind(oneDayAgo)
      .first<{ c: number }>()
    todayConversations = recentConvs?.c || 0

    const totalMsgs = await db.prepare('SELECT COUNT(*) as c FROM messages').first<{ c: number }>()
    totalMessages = totalMsgs?.c || 0
  }

  const onlineAgents = await db
    .prepare("SELECT COUNT(*) as c FROM agents WHERE status != 'offline'")
    .first<{ c: number }>()

  return {
    totalConversations,
    totalMessages,
    onlineAgents: onlineAgents?.c || 0,
    todayConversations,
    site_id: site
  }
}
