/**
 * 多语言系统设置键与浏览器语种匹配（欢迎语 / 离线回复等）
 */

/** 同一语种在 settings 中可能出现的键名变体（兼容历史写入） */
export function settingKeyCandidates(baseKey: string, langCode: string): string[] {
  const code = (langCode || '').trim()
  if (!code) return [baseKey]
  const lower = code.toLowerCase()
  const underscored = lower.replace(/-/g, '_')
  const dashed = underscored.replace(/_/g, '-')
  const primary = lower.split(/[-_]/)[0]
  const keys = [
    `${baseKey}_${code}`,
    `${baseKey}_${lower}`,
    `${baseKey}_${underscored}`,
    `${baseKey}_${dashed}`,
    `${baseKey}_${primary}`
  ]
  return [...new Set(keys)]
}

/** 从 settings 字典按语种读取，找不到再回退 baseKey */
export function getSettingForLang(
  settings: Record<string, string | undefined | null>,
  baseKey: string,
  langCode: string,
  fallback = ''
): string {
  for (const key of settingKeyCandidates(baseKey, langCode)) {
    const val = settings[key]
    if (val != null && String(val).trim() !== '') return String(val)
  }
  const bare = settings[baseKey]
  if (bare != null && String(bare).trim() !== '') return String(bare)
  return fallback
}

/** 写入时使用稳定键：base_原始语种code（与后台编辑页一致） */
export function settingKeyForLang(baseKey: string, langCode: string): string {
  return `${baseKey}_${langCode}`
}

export interface LangOption {
  code: string
  name: string
  is_default?: number
}

/**
 * 匹配浏览器语言到已启用语种；无匹配时优先英语，再默认语种
 */
export function resolveVisitorLang(
  browserLang: string | undefined,
  languages: LangOption[],
  manualLang?: string | null
): string {
  if (!languages.length) return 'en'

  if (manualLang && languages.some(l => l.code === manualLang)) {
    return manualLang
  }

  const nav = (browserLang || '').trim()
  if (nav) {
    const exact = languages.find(l => l.code === nav)
    if (exact) return exact.code

    const navNorm = nav.toLowerCase().replace(/_/g, '-')
    const ci = languages.find(l => l.code.toLowerCase().replace(/_/g, '-') === navNorm)
    if (ci) return ci.code

    // 完整区域优先（zh-TW 不应落到 zh-CN）
    const navPrefix = navNorm.split('-')[0]
    const regionHits = languages.filter(l => {
      const c = l.code.toLowerCase().replace(/_/g, '-')
      return c === navNorm || c.startsWith(navNorm + '-') || c === navPrefix
    })
    if (regionHits.length === 1) return regionHits[0].code
    if (regionHits.length > 1) {
      const full = regionHits.find(l => l.code.toLowerCase().replace(/_/g, '-') === navNorm)
      if (full) return full.code
      const prefixOnly = regionHits.find(l => l.code.toLowerCase().replace(/_/g, '-') === navPrefix)
      if (prefixOnly && navNorm === navPrefix) return prefixOnly.code
      // zh-TW 有 zh-tw：上面 ci 已覆盖；若只有 zh-CN 与 en，zh-TW 不应误选 zh-CN
      if (navPrefix === 'zh' && navNorm.includes('-')) {
        const tw = regionHits.find(l => /zh[-_]tw/i.test(l.code))
        const cn = regionHits.find(l => /zh[-_]cn/i.test(l.code))
        if (navNorm.includes('tw') && tw) return tw.code
        if ((navNorm.includes('cn') || navNorm === 'zh-hans') && cn) return cn.code
      }
    }
  }

  const en = languages.find(l => l.code.toLowerCase() === 'en' || l.code.toLowerCase().startsWith('en-'))
  if (en) return en.code

  const def = languages.find(l => l.is_default === 1) || languages[0]
  return def.code
}

/** Fallback welcome/offline copy when a locale has no saved setting (English source). */
export const DEFAULT_WELCOME_MESSAGE =
  'Hello! Welcome to live chat. How can we help you?'
export const DEFAULT_OFFLINE_MESSAGE =
  'No agents are online right now. Please leave your contact details and we will get back to you soon.'
