import type { Env } from '../types'
import { getSystemSettings } from '../db/settings'

export interface LeaveMessageData {
  visitor_name: string
  contact: string
  content: string
  conversation_id?: string
  visitor_id?: string
  ip?: string
}

export interface NotifyResult {
  email?: { success: boolean; provider?: 'resend' | 'useplunk'; error?: any }
  telegram?: { success: boolean; error?: any }
  wecom?: { success: boolean; error?: any }
}

/**
 * 1. Resend 邮件发送引擎
 */
async function sendViaResend(
  apiKey: string,
  fromEmail: string,
  toEmail: string,
  subject: string,
  html: string
): Promise<{ success: boolean; data?: any; error?: any }> {
  try {
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey.trim()}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        from: fromEmail.trim() || 'Cloudflare IM <onboarding@resend.dev>',
        to: [toEmail.trim()],
        subject,
        html
      })
    })
    const data = await res.json()
    if (res.ok) {
      return { success: true, data }
    }
    return { success: false, error: data }
  } catch (err: any) {
    return { success: false, error: err.message }
  }
}

/**
 * 2. UsePlunk 邮件发送引擎 (useplunk.com) - 高可用备用容灾
 */
async function sendViaUsePlunk(
  secretKey: string,
  fromEmail: string,
  toEmail: string,
  subject: string,
  html: string
): Promise<{ success: boolean; data?: any; error?: any }> {
  try {
    const res = await fetch('https://next-api.useplunk.com/v1/send', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${secretKey.trim()}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        to: toEmail.trim(),
        subject,
        body: html,
        from: fromEmail.trim() || undefined
      })
    })
    const data = await res.json()
    if (res.ok) {
      return { success: true, data }
    }
    return { success: false, error: data }
  } catch (err: any) {
    return { success: false, error: err.message }
  }
}

/**
 * 3. 邮件发送高可用容灾调度器 (Resend 额度耗尽或报错后自动降级到 UsePlunk)
 */
async function sendEmailWithFailover(
  toEmail: string,
  subject: string,
  html: string,
  settings: Record<string, string>
): Promise<{ success: boolean; provider?: 'resend' | 'useplunk'; error?: any }> {
  const resendKey = settings['resend_api_key']
  const plunkKey = settings['plunk_secret_key']

  // 1. 优先尝试 Resend
  if (resendKey) {
    const resendRes = await sendViaResend(
      resendKey,
      settings['resend_from_email'] || 'onboarding@resend.dev',
      toEmail,
      subject,
      html
    )
    if (resendRes.success) {
      return { success: true, provider: 'resend' }
    }
    console.warn('Resend send failed, falling back to UsePlunk...', resendRes.error)
  }

  // 2. Resend 失败、额度用完或未配置时，自动降级切换到 UsePlunk
  if (plunkKey) {
    const plunkRes = await sendViaUsePlunk(
      plunkKey,
      settings['plunk_from_email'] || '',
      toEmail,
      subject,
      html
    )
    if (plunkRes.success) {
      return { success: true, provider: 'useplunk' }
    }
    return { success: false, provider: 'useplunk', error: plunkRes.error }
  }

  return { success: false, error: 'No valid email API key configured (Resend or UsePlunk)' }
}

/**
 * 4. Telegram 机器人消息推送
 */
async function sendViaTelegram(
  botToken: string,
  chatId: string,
  text: string
): Promise<{ success: boolean; error?: any }> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken.trim()}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: chatId.trim(),
        text,
        parse_mode: 'HTML'
      })
    })
    const data = await res.json() as any
    if (data.ok) {
      return { success: true }
    }
    return { success: false, error: data.description }
  } catch (err: any) {
    return { success: false, error: err.message }
  }
}

/**
 * 5. 企业微信群机器人推送
 */
async function sendViaWeCom(
  webhookUrl: string,
  markdownText: string
): Promise<{ success: boolean; error?: any }> {
  try {
    let url = webhookUrl.trim()
    if (!url.startsWith('http')) {
      url = `https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=${url}`
    }
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        msgtype: 'markdown',
        markdown: { content: markdownText }
      })
    })
    const data = await res.json() as any
    if (data.errcode === 0) {
      return { success: true }
    }
    return { success: false, error: data.errmsg }
  } catch (err: any) {
    return { success: false, error: err.message }
  }
}

/**
 * 全渠道离线留言通知统一调度分发
 */
export async function dispatchLeaveMessageNotification(
  env: Env,
  data: LeaveMessageData
): Promise<NotifyResult> {
  const settings = await getSystemSettings(env.DB)
  const channels = (settings['notify_channels'] || '').split(',').map(s => s.trim())
  const result: NotifyResult = {}

  const timeStr = new Date().toLocaleString('en-US', { timeZone: 'UTC' })

  // 1. Email (Resend + UsePlunk failover)
  const toEmail = settings['notify_email_to']
  if (channels.includes('email') && toEmail) {
    const subject = `[Live chat] New offline message from [${data.visitor_name}]`
    const html = `
      <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; border: 1px solid #e5e7eb; rounded: 16px;">
        <h2 style="color: #111827; margin-bottom: 16px; font-size: 18px; border-bottom: 2px solid #07c160; padding-bottom: 8px;">New offline visitor message</h2>
        <table style="width: 100%; border-collapse: collapse; font-size: 14px; color: #374151;">
          <tr>
            <td style="padding: 8px 0; font-weight: bold; width: 90px;">Name:</td>
            <td style="padding: 8px 0; color: #111827;">${data.visitor_name}</td>
          </tr>
          <tr>
            <td style="padding: 8px 0; font-weight: bold;">Contact:</td>
            <td style="padding: 8px 0; color: #2563eb; font-weight: 600;">${data.contact}</td>
          </tr>
          <tr>
            <td style="padding: 8px 0; font-weight: bold;">Time:</td>
            <td style="padding: 8px 0; color: #6b7280;">${timeStr}</td>
          </tr>
        </table>
        <div style="margin-top: 16px; padding: 14px; background-color: #f9fafb; border-left: 4px solid #07c160; border-radius: 4px;">
          <div style="font-weight: bold; font-size: 13px; color: #4b5563; margin-bottom: 6px;">Message:</div>
          <div style="font-size: 14px; color: #111827; line-height: 1.6; white-space: pre-wrap;">${data.content}</div>
        </div>
        <div style="margin-top: 20px; font-size: 12px; color: #9ca3af; text-align: center;">
          Sent automatically by the live chat system. Please follow up in the admin console.
        </div>
      </div>
    `
    result.email = await sendEmailWithFailover(toEmail, subject, html, settings)
  }

  // 2. Telegram
  const tgToken = settings['telegram_bot_token']
  const tgChatId = settings['telegram_chat_id']
  if (channels.includes('telegram') && tgToken && tgChatId) {
    const tgMsg =
      `🔔 <b>[Live chat] New offline visitor message</b>\n\n` +
      `👤 <b>Name:</b> ${data.visitor_name}\n` +
      `📞 <b>Contact:</b> <code>${data.contact}</code>\n` +
      `⏰ <b>Time:</b> ${timeStr}\n\n` +
      `💬 <b>Message:</b>\n${data.content}`
    result.telegram = await sendViaTelegram(tgToken, tgChatId, tgMsg)
  }

  // 3. WeCom
  const wecomUrl = settings['wecom_webhook_url']
  if (channels.includes('wecom') && wecomUrl) {
    const wecomMsg =
      `### New offline visitor message\n` +
      `> **Name**: <font color="info">${data.visitor_name}</font>\n` +
      `> **Contact**: <font color="warning">${data.contact}</font>\n` +
      `> **Time**: ${timeStr}\n\n` +
      `**Message**:\n${data.content}`
    result.wecom = await sendViaWeCom(wecomUrl, wecomMsg)
  }

  return result
}
