import type { Env, Message, WSPacket } from './types'
import { insertMessage, markConversationAsRead, getMessagesByConversation } from './db/messages'
import { getOrCreateConversation } from './db/conversations'
import { askKnowledge } from './services/kbService'
import { getSiteSettingsMap } from './db/sites'
import { getSystemSetting } from './db/settings'
import { assertInternalRequest } from './utils/sessionToken'

async function resolveSiteAiSetting(
  db: D1Database,
  siteId: string | null | undefined,
  key: string
): Promise<string | null> {
  const sid = (siteId || '').trim()
  if (sid) {
    try {
      const map = await getSiteSettingsMap(db, sid)
      const v = map[key]
      if (v != null && String(v).trim() !== '') return String(v)
    } catch {
      /* ignore */
    }
  }
  return getSystemSetting(db, key)
}

/**
 * 实时通讯协调器 (ChatCoordinator)
 * 基于 Cloudflare SQLite Durable Object 与 WebSocket Hibernation 实现
 * 负责跨会话与客服长连接管理、状态监听与毫秒级广播
 */
export class ChatCoordinator implements DurableObject {
  ctx: DurableObjectState
  env: Env

  constructor(ctx: DurableObjectState, env: Env) {
    this.ctx = ctx
    this.env = env
  }

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url)
    const upgradeHeader = request.headers.get('Upgrade')

    // 内部 HTTP 广播端点：必须带 Worker 签发的内部密钥
    if (
      (url.pathname === '/broadcast-status' ||
        url.pathname === '/broadcast-message' ||
        url.pathname === '/broadcast-deleted') &&
      request.method === 'POST'
    ) {
      if (!assertInternalRequest(this.env, request)) {
        return new Response(JSON.stringify({ success: false, error: 'forbidden' }), {
          status: 403,
          headers: { 'Content-Type': 'application/json' }
        })
      }
    }

    if (url.pathname === '/broadcast-status' && request.method === 'POST') {
      try {
        const body = await request.json()
        const sockets = this.ctx.getWebSockets()
        const payload = JSON.stringify({
          type: 'agent_status_change',
          data: body
        })
        for (const s of sockets) {
          try {
            s.send(payload)
          } catch (err) {}
        }
        return new Response(JSON.stringify({ success: true }), {
          headers: { 'Content-Type': 'application/json' }
        })
      } catch (e: any) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 })
      }
    }

    if (url.pathname === '/broadcast-message' && request.method === 'POST') {
      try {
        const savedMsg = await request.json() as any
        this.broadcastToConversation(savedMsg.conversation_id, {
          type: 'message',
          data: savedMsg
        })
        this.broadcastToAgents({
          type: 'message',
          data: savedMsg
        })
        this.broadcastToAgents({
          type: 'conversation_update',
          data: {
            conversation_id: savedMsg.conversation_id,
            last_message: savedMsg
          }
        })
        return new Response(JSON.stringify({ success: true }), {
          headers: { 'Content-Type': 'application/json' }
        })
      } catch (e: any) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 })
      }
    }

    if (url.pathname === '/broadcast-deleted' && request.method === 'POST') {
      try {
        const body = (await request.json()) as {
          conversation_id?: string
          clear_identity?: boolean
        }
        if (body.conversation_id) {
          this.broadcastToConversation(body.conversation_id, {
            type: 'conversation_deleted',
            data: {
              conversation_id: body.conversation_id,
              clear_identity: body.clear_identity !== false
            }
          })
        }
        return new Response(JSON.stringify({ success: true }), {
          headers: { 'Content-Type': 'application/json' }
        })
      } catch (e: any) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 })
      }
    }

    if (upgradeHeader !== 'websocket') {
      return new Response('Expected WebSocket upgrade', { status: 426 })
    }

    const role = url.searchParams.get('role') || 'visitor'
    const conversationId = url.searchParams.get('cid') || ''
    const userId = url.searchParams.get('uid') || ''
    const siteId = url.searchParams.get('site') || ''

    // 创建 WebSocket 客户端与服务端对
    const webSocketPair = new WebSocketPair()
    const [client, server] = Object.values(webSocketPair)

    // NOTE: 使用 WebSocket Hibernation API 打标签，长连接休眠时不消耗计费时长
    const tags: string[] = [`role:${role}`]
    if (conversationId) {
      tags.push(`cid:${conversationId}`)
    }
    if (userId) {
      tags.push(`uid:${userId}`)
    }
    if (siteId) {
      tags.push(`site:${siteId}`)
    }

    this.ctx.acceptWebSocket(server, tags)

    // 给刚连上的客户端发送一个初始握手包
    server.send(JSON.stringify({
      type: 'init',
      data: {
        status: 'connected',
        role,
        conversationId,
        serverTime: Date.now()
      }
    }))

    return new Response(null, {
      status: 101,
      webSocket: client
    })
  }

  /**
   * 当收到客户端 WebSocket 消息时触发
   */
  async webSocketMessage(ws: WebSocket, rawMessage: string | ArrayBuffer): Promise<void> {
    try {
      const text = typeof rawMessage === 'string' ? rawMessage : new TextDecoder().decode(rawMessage)
      const packet = JSON.parse(text) as WSPacket

      if (packet.type === 'message') {
        const msgPayload = packet.data as Message
        if (!msgPayload || !msgPayload.conversation_id || !msgPayload.content) {
          return
        }

        // 旧 cid 已删 / pending_* 临时 id：按 visitor 创建或复用会话，并通知前端换新 id
        const cid = msgPayload.conversation_id
        const needsEnsure =
          !cid ||
          cid.startsWith('pending_') ||
          !(
            await this.env.DB.prepare('SELECT id FROM conversations WHERE id = ?')
              .bind(cid)
              .first<{ id: string }>()
          )

        if (needsEnsure) {
          if (msgPayload.sender_type !== 'visitor' || !msgPayload.sender_id) {
            try {
              ws.send(
                JSON.stringify({
                  type: 'error',
                  data: { code: 'conversation_not_found', conversation_id: cid }
                })
              )
            } catch {
              /* ignore */
            }
            return
          }

          const tags = this.ctx.getTags(ws) || []
          const siteTag = tags.find(t => t.startsWith('site:'))
          let siteId = siteTag ? siteTag.slice(5) : ''
          if (!siteId && cid && !cid.startsWith('pending_')) {
            const row = await this.env.DB.prepare(
              'SELECT site_id FROM conversations WHERE id = ?'
            )
              .bind(cid)
              .first<{ site_id: string | null }>()
            siteId = row?.site_id || ''
          }
          if (!siteId) {
            try {
              ws.send(
                JSON.stringify({
                  type: 'error',
                  data: { code: 'site_required', conversation_id: cid }
                })
              )
            } catch {
              /* ignore */
            }
            return
          }

          const { conversation } = await getOrCreateConversation(
            this.env.DB,
            msgPayload.sender_id,
            siteId,
            msgPayload.sender_name
          )
          const replaced = conversation.id !== cid
          msgPayload.conversation_id = conversation.id
          if (replaced) {
            try {
              ws.send(
                JSON.stringify({
                  type: 'session_replaced',
                  data: { conversation, reason: 'conversation_missing' }
                })
              )
            } catch {
              /* ignore */
            }
          }
        }

        // 1. 持久化到 Cloudflare D1 边缘数据库
        const savedMsg = await insertMessage(this.env.DB, msgPayload)

        // 2. 广播给该会话中的所有订阅者 (访客自身与正在查看该会话的端)
        this.broadcastToConversation(savedMsg.conversation_id, {
          type: 'message',
          data: savedMsg
        })

        // 3. 同时广播给所有客服：message 更新打开中的会话窗；conversation_update 刷新列表/未读
        this.broadcastToAgents({
          type: 'message',
          data: savedMsg
        })
        this.broadcastToAgents({
          type: 'conversation_update',
          data: {
            conversation_id: savedMsg.conversation_id,
            last_message: savedMsg
          }
        })

        // 4. 按会话所属站点触发本站知识库 AI 自动问答
        if (savedMsg.sender_type === 'visitor' && savedMsg.message_type === 'text') {
          this.ctx.waitUntil((async () => {
            const publishAiText = async (content: string) => {
              const aiMsgPayload: Message = {
                id: `msg_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
                conversation_id: savedMsg.conversation_id,
                sender_type: 'agent',
                sender_id: 'ai_bot',
                sender_name: 'AI Assistant',
                message_type: 'text',
                content,
                status: 'sent',
                created_at: Date.now()
              }
              const savedAiMsg = await insertMessage(this.env.DB, aiMsgPayload)
              this.broadcastToConversation(savedAiMsg.conversation_id, {
                type: 'message',
                data: savedAiMsg
              })
              this.broadcastToAgents({
                type: 'message',
                data: savedAiMsg
              })
              this.broadcastToAgents({
                type: 'conversation_update',
                data: {
                  conversation_id: savedAiMsg.conversation_id,
                  last_message: savedAiMsg
                }
              })
            }

            try {
              const convRow = await this.env.DB.prepare(
                'SELECT site_id FROM conversations WHERE id = ?'
              )
                .bind(savedMsg.conversation_id)
                .first<{ site_id: string | null }>()
              const siteId = (convRow?.site_id || '').trim() || null

              const strategy =
                (await resolveSiteAiSetting(this.env.DB, siteId, 'ai_reply_strategy')) || 'always'
              if (strategy === 'disabled') return

              const lower = savedMsg.content.toLowerCase()
              const isExplicitAi = lower.startsWith('@ai') || lower.startsWith('@bot')
              let shouldTrigger = false

              if (isExplicitAi) {
                shouldTrigger = true
              } else if (strategy === 'always') {
                shouldTrigger = true
              } else if (strategy === 'offline_only') {
                const onlineRes = await this.env.DB.prepare(
                  "SELECT count(1) as count FROM agents WHERE status = 'online'"
                ).first<{ count: number }>()
                const hasOnlineAgent = (onlineRes?.count || 0) > 0
                const agentSockets = this.ctx.getWebSockets('role:agent')
                const hasRealAgent = hasOnlineAgent && agentSockets.length > 0
                shouldTrigger = !hasRealAgent
              }

              if (!shouldTrigger) return

              const queryText = savedMsg.content.replace(/^@(?:ai|bot)\s*/i, '').trim()
              if (!queryText) return

              const recentMsgs = await getMessagesByConversation(
                this.env.DB,
                savedMsg.conversation_id,
                4
              )
              const convHistory = recentMsgs.reverse().map(m => ({
                role: (m.sender_type === 'visitor' ? 'user' : 'assistant') as 'user' | 'assistant',
                content: m.content
              }))

              const { answer } = await askKnowledge(this.env, queryText, convHistory, { siteId })
              if (answer) {
                await publishAiText(answer)
              } else {
                await publishAiText(
                  'AI assistant could not generate a reply right now. An agent will follow up shortly.'
                )
              }
            } catch (e: any) {
              console.warn('Failed to auto answer with KB RAG', e)
              try {
                const detail = String(e?.message || e || 'unknown error').slice(0, 160)
                await publishAiText(
                  `AI assistant is temporarily unavailable (${detail}). An agent will follow up shortly.`
                )
              } catch {
                /* ignore secondary failure */
              }
            }
          })())
        }
      } else if (packet.type === 'visitor_name_update') {
        // 仅允许：访客角色 + socket.uid 与会话 visitor_id 一致 + cid 匹配
        const name = String(packet.data?.name || '')
          .trim()
          .replace(/[<>]/g, '')
          .slice(0, 64)
        const convId = String(packet.data?.conversation_id || '').trim()
        const tags = this.ctx.getTags(ws)
        const role = tags.find(t => t.startsWith('role:'))?.slice(5)
        const uid = tags.find(t => t.startsWith('uid:'))?.slice(4) || ''
        const taggedCid = tags.find(t => t.startsWith('cid:'))?.slice(4) || ''
        if (
          name &&
          convId &&
          role === 'visitor' &&
          uid &&
          (!taggedCid || taggedCid === convId || taggedCid.startsWith('pending_'))
        ) {
          try {
            const conv = await this.env.DB.prepare(
              'SELECT id, visitor_id FROM conversations WHERE id = ?'
            )
              .bind(convId)
              .first<{ id: string; visitor_id: string }>()
            if (conv && conv.visitor_id === uid) {
              await this.env.DB.prepare('UPDATE conversations SET visitor_name = ? WHERE id = ?')
                .bind(name, convId)
                .run()
              this.broadcastToAgents({
                type: 'conversation_update',
                data: { conversation_id: convId, visitor_name: name }
              })
              try {
                ws.send(
                  JSON.stringify({ type: 'visitor_name_ok', data: { conversation_id: convId, name } })
                )
              } catch {
                /* ignore */
              }
            }
          } catch (e) {
            console.warn('[DO] visitor_name_update failed', e)
          }
        }
      } else if (packet.type === 'read') {
        // 已读上报
        const { conversation_id, by } = packet.data || {}
        if (conversation_id && by) {
          await markConversationAsRead(this.env.DB, conversation_id, by)
          this.broadcastToConversation(conversation_id, {
            type: 'read',
            data: { conversation_id, by }
          })
        }
      } else if (
        packet.type === 'call_invite' ||
        packet.type === 'call_accept' ||
        packet.type === 'call_reject' ||
        packet.type === 'call_hangup' ||
        packet.type === 'webrtc_offer' ||
        packet.type === 'webrtc_answer' ||
        packet.type === 'webrtc_ice'
      ) {
        // WebRTC 实时音视频信令转发
        const convId = packet.data?.conversation_id
        if (convId) {
          this.broadcastToConversation(convId, packet)
        }
      } else if (packet.type === 'pong') {
        // 心跳应答，保持存活
      }
    } catch (err) {
      console.error('Error handling websocket message:', err)
    }
  }

  /**
   * 当 WebSocket 连接关闭时触发
   */
  async webSocketClose(ws: WebSocket, code: number, reason: string, wasClean: boolean): Promise<void> {
    ws.close(code, reason)
  }

  /**
   * 当 WebSocket 出现错误时触发
   */
  async webSocketError(ws: WebSocket, error: unknown): Promise<void> {
    console.error('WebSocket error:', error)
  }

  /**
   * 向指定会话的所有活跃连接广播数据包
   */
  private broadcastToConversation(conversationId: string, packet: any): void {
    const sockets = this.ctx.getWebSockets(`cid:${conversationId}`)
    const payload = JSON.stringify(packet)
    for (const ws of sockets) {
      try {
        ws.send(payload)
      } catch (e) {
        console.warn('Failed to send to client socket:', e)
      }
    }
  }

  /**
   * 向所有在线客服连接广播数据包
   */
  private broadcastToAgents(packet: any): void {
    const sockets = this.ctx.getWebSockets('role:agent')
    const payload = JSON.stringify(packet)
    for (const ws of sockets) {
      try {
        ws.send(payload)
      } catch (e) {
        console.warn('Failed to send to agent socket:', e)
      }
    }
  }
}
