/** Resolve admin UI locale from X-UI-Locale or Accept-Language. Default: en. */

const SUPPORTED = new Set(['en', 'zh-CN', 'zh-TW', 'ja', 'es', 'pt', 'ar'])

export type ApiLocale = 'en' | 'zh-CN' | 'zh-TW' | 'ja' | 'es' | 'pt' | 'ar'

export function normalizeApiLocale(raw: string | null | undefined): ApiLocale {
  if (!raw) return 'en'
  const s = raw.trim().replace(/_/g, '-')
  if (SUPPORTED.has(s)) return s as ApiLocale
  const lower = s.toLowerCase()
  if (lower.startsWith('zh-tw') || lower === 'zh-hk' || lower === 'zh-hant') return 'zh-TW'
  if (lower.startsWith('zh')) return 'zh-CN'
  if (lower.startsWith('ja')) return 'ja'
  if (lower.startsWith('es')) return 'es'
  if (lower.startsWith('pt')) return 'pt'
  if (lower.startsWith('ar')) return 'ar'
  if (lower.startsWith('en')) return 'en'
  return 'en'
}

export function resolveApiLocaleFromHeaders(getHeader: (name: string) => string | undefined): ApiLocale {
  const explicit = getHeader('X-UI-Locale') || getHeader('x-ui-locale')
  if (explicit) return normalizeApiLocale(explicit)

  const accept = getHeader('Accept-Language') || getHeader('accept-language')
  if (!accept) return 'en'
  const first = accept.split(',')[0]?.trim().split(';')[0]
  return normalizeApiLocale(first)
}
