/**
 * 知识库系统路由层
 * 涵盖：智能客服 RAG 问答、本地营销文案 AI 工具生成接口、知识库管理与 CMS 一键同步
 */
import { Hono } from 'hono'
import type { Env, KbDocument, KbDomain, KbProductData, AiModelChannel, AiEngineConfig, AiReplyStrategy } from '../types'
import {
  getKbDocuments,
  getKbDocumentById,
  saveKbDocument,
  deleteKbDocument
} from '../db/kb'
import {
  indexDocument,
  searchKnowledge,
  askKnowledge,
  DEFAULT_MODEL_POOL,
  normalizeModelPool,
  testAiChannel,
  translateContentWithAi,
  type AiTranslateParams
} from '../services/kbService'
import { getCmsProducts, getCmsProductById, getCmsArticles } from '../db/cms'
import { getSystemSetting, updateSystemSettings } from '../db/settings'
import { updateSiteSettings, getSiteSettingsMap } from '../db/sites'
import { isErrorResponse, requireAdmin } from '../middleware/auth'

export const kbRouter = new Hono<{ Bindings: Env }>()

/** 后台知识库 / AI 管理接口统一要求管理员登录 */
kbRouter.use('/admin/kb/*', async (c, next) => {
  const admin = await requireAdmin(c)
  if (isErrorResponse(admin)) return admin
  await next()
})

function readSiteId(c: any, body?: any): string {
  return (
    (c.req.query('site_id') || '').trim() ||
    (c.req.header('X-Site-Id') || '').trim() ||
    (typeof body?.site_id === 'string' ? body.site_id.trim() : '')
  )
}

async function readAiConfigForSite(db: D1Database, siteId: string) {
  const siteMap = siteId ? await getSiteSettingsMap(db, siteId) : {}
  const pick = async (key: string, fallback = '') => {
    const local = siteMap[key]
    if (local != null && String(local).trim() !== '') return String(local)
    return (await getSystemSetting(db, key)) || fallback
  }
  return {
    strategy: ((await pick('ai_reply_strategy', 'always')) as AiReplyStrategy) || 'always',
    systemPrompt: await pick('ai_system_prompt', ''),
    poolJson: await pick('ai_model_pool', ''),
    ticketAutoReplyStr: await pick('ai_ticket_auto_reply', 'true')
  }
}

/**
 * 校验外部本地营销软件访问 API Key (通过 Authorization: Bearer <TOKEN> 或 X-Api-Key)
 */
function checkApiKey(c: any): boolean {
  const secret = c.env.KB_API_TOKEN || c.env.ADMIN_SECURITY_CODE
  if (!secret) return true // 未配置安全凭证时允许免密（本地轻量体验）
  const authHeader = c.req.header('Authorization') || ''
  const bearerToken = authHeader.startsWith('Bearer ') ? authHeader.substring(7).trim() : ''
  const apiKey = c.req.header('x-api-key') || c.req.query('api_key') || bearerToken
  return apiKey === secret
}

// ==================== 1. 面向本地软件大模型与前台客服的数据接口 ====================

// 智能客服问答接口 (供前台在线客服或外部问答调用)
kbRouter.post('/kb/ask', async (c) => {
  try {
    const body = await c.req.json()
    const question = body.question?.trim()
    if (!question) {
      return c.json({ status: 400, msg: 'Question cannot be empty', data: null }, 400)
    }

    const history = Array.isArray(body.history) ? body.history : []
    const siteId = readSiteId(c, body) || null
    const result = await askKnowledge(c.env, question, history, { siteId })

    return c.json({ status: 200, msg: 'ok', data: result }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Knowledge Q&A error: ' + err.message, data: null }, 500)
  }
})

// 知识库切片相似度检索接口 (专为本地大模型 RAG 上下文召回提供)
kbRouter.post('/kb/search', async (c) => {
  try {
    if (!checkApiKey(c)) {
      return c.json({ status: 401, msg: 'Unauthorized: invalid or missing API key', data: null }, 401)
    }

    const body = await c.req.json()
    const query = body.query?.trim()
    if (!query) {
      return c.json({ status: 400, msg: 'Search query cannot be empty', data: null }, 400)
    }

    const domains: KbDomain[] | undefined = body.domain ? [body.domain] : body.domains
    const results = await searchKnowledge(c.env, query, {
      domains,
      relProductId: body.productId,
      topK: body.topK || 4
    })

    return c.json({ status: 200, msg: 'ok', data: results }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Retrieval failed: ' + err.message, data: null }, 500)
  }
})

// 本地大模型结构化产品数据提取端点 (供本地营销软件直接读取官方参数、卖点、定价全貌)
kbRouter.get('/kb/products-data', async (c) => {
  try {
    if (!checkApiKey(c)) {
      return c.json({ status: 401, msg: 'Unauthorized: invalid or missing API key', data: null }, 401)
    }

    const search = c.req.query('search')
    const categoryId = c.req.query('categoryId')
    const lang = c.req.query('lang') || 'zh-CN'
    const limit = Number(c.req.query('limit')) || 50

    const productsRes = await getCmsProducts(c.env.DB, {
      search,
      categoryId,
      lang,
      pageSize: limit,
      status: 'active'
    })

    const formattedList: KbProductData[] = productsRes.list.map(p => ({
      id: p.id,
      title: p.title || p.slug,
      category_name: p.category?.name || undefined,
      slug: p.slug,
      price: p.price,
      price_currency: p.price_currency,
      sku: p.sku,
      brand: p.brand,
      availability: p.availability || 'in_stock',
      summary: p.summary || '',
      description: p.description || '',
      specs: typeof p.spec_data === 'object' ? JSON.stringify(p.spec_data) : String(p.spec_data || ''),
      cover: p.cover,
      updated_at: p.updated_at
    }))

    return c.json({ status: 200, msg: 'ok', data: formattedList }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load product data: ' + err.message, data: null }, 500)
  }
})

// 获取单款产品的完整结构化档案及关联知识文档 (供本地大模型做深度产品文案时提取全景上下文)
kbRouter.get('/kb/products-data/:id', async (c) => {
  try {
    if (!checkApiKey(c)) {
      return c.json({ status: 401, msg: 'Unauthorized: invalid or missing API key', data: null }, 401)
    }

    const id = c.req.param('id')
    const lang = c.req.query('lang') || 'zh-CN'
    const product = await getCmsProductById(c.env.DB, id, lang)

    if (!product) {
      return c.json({ status: 404, msg: 'Product not found', data: null }, 404)
    }

    const productData: KbProductData = {
      id: product.id,
      title: product.title || product.slug,
      category_name: product.category?.name || undefined,
      slug: product.slug,
      price: product.price,
      price_currency: product.price_currency,
      sku: product.sku,
      brand: product.brand,
      availability: product.availability || 'in_stock',
      summary: product.summary || '',
      description: product.description || '',
      specs: typeof product.spec_data === 'object' ? JSON.stringify(product.spec_data) : String(product.spec_data || ''),
      cover: product.cover,
      updated_at: product.updated_at
    }

    // 同时拉取与该产品直接关联的知识库文档（如详细说明书、FAQ、卖点分析文档）
    const relatedDocs = await getKbDocuments(c.env.DB, { relProductId: id })

    return c.json({
      status: 200,
      msg: 'ok',
      data: {
        product: productData,
        related_knowledge: relatedDocs.map(d => ({ id: d.id, title: d.title, content: d.content }))
      }
    }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load product details: ' + err.message, data: null }, 500)
  }
})

// ==================== 2. 后台知识库管理接口 ====================

// 获取知识库文档列表
kbRouter.get('/admin/kb/documents', async (c) => {
  try {
    const siteId = readSiteId(c)
    if (!siteId) {
      return c.json({ status: 400, msg: 'Select a site (site_id / X-Site-Id)', data: null }, 400)
    }
    const domain = c.req.query('domain') as KbDomain | undefined
    const search = c.req.query('search')
    const relProductId = c.req.query('productId')

    const docs = await getKbDocuments(c.env.DB, {
      siteId,
      domain,
      search,
      relProductId
    })

    return c.json({ status: 200, msg: 'ok', data: docs }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load knowledge base: ' + err.message, data: null }, 500)
  }
})

// 获取单篇文档详情
kbRouter.get('/admin/kb/documents/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const doc = await getKbDocumentById(c.env.DB, id)
    if (!doc) {
      return c.json({ status: 404, msg: 'Document not found', data: null }, 404)
    }
    return c.json({ status: 200, msg: 'ok', data: doc }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load documents: ' + err.message, data: null }, 500)
  }
})

// 新建或编辑保存文档 (自动触发分块与向量化)
kbRouter.post('/admin/kb/documents', async (c) => {
  try {
    const body = await c.req.json()
    const siteId = readSiteId(c, body)
    if (!siteId) {
      return c.json({ status: 400, msg: 'Select a site (site_id / X-Site-Id)', data: null }, 400)
    }
    const { id, domain = 'support', title, content, rel_product_id, tags } = body

    if (!title?.trim() || !content?.trim()) {
      return c.json({ status: 400, msg: 'Document title and body are required', data: null }, 400)
    }

    const docId = id || `doc_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`
    const now = Date.now()

    const doc: KbDocument = {
      id: docId,
      site_id: siteId,
      domain,
      title: title.trim(),
      content: content.trim(),
      rel_product_id: rel_product_id || null,
      tags_json: tags ? JSON.stringify(tags) : null,
      chunks_count: 0,
      status: 'indexing',
      created_at: now,
      updated_at: now
    }

    // 先入库
    await saveKbDocument(c.env.DB, doc)

    // 触发分块与向量化
    const indexRes = await indexDocument(c.env, doc)

    return c.json({
      status: 200,
      msg: 'Document saved',
      data: { id: docId, chunks_count: indexRes.chunksCount, status: indexRes.success ? 'ready' : 'error' }
    }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to save knowledge document: ' + err.message, data: null }, 500)
  }
})

// 删除文档及对应向量切片
kbRouter.delete('/admin/kb/documents/:id', async (c) => {
  try {
    const id = c.req.param('id')
    const deletedVecIds = await deleteKbDocument(c.env.DB, id)

    // 同步从 Vectorize 清除
    if (c.env.VECTORIZE_INDEX && deletedVecIds.length > 0) {
      try {
        await c.env.VECTORIZE_INDEX.deleteByIds(deletedVecIds)
      } catch (e) {
        console.warn('Failed to delete vectors from Vectorize', e)
      }
    }

    return c.json({ status: 200, msg: 'Document and vectors removed', data: { id, deleted_chunks: deletedVecIds.length } }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to delete document: ' + err.message, data: null }, 500)
  }
})

// 手动重新索引文档
kbRouter.post('/admin/kb/documents/:id/reindex', async (c) => {
  try {
    const id = c.req.param('id')
    const doc = await getKbDocumentById(c.env.DB, id)
    if (!doc) {
      return c.json({ status: 404, msg: 'Document not found', data: null }, 404)
    }

    const indexRes = await indexDocument(c.env, doc)
    return c.json({ status: 200, msg: 'Re-index succeeded', data: indexRes }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Re-index failed: ' + err.message, data: null }, 500)
  }
})

// 知识库召回效果调试台 (Test Query Playground)
kbRouter.post('/admin/kb/test-query', async (c) => {
  try {
    const body = await c.req.json()
    const query = body.query?.trim()
    if (!query) {
      return c.json({ status: 400, msg: 'Debug question cannot be empty', data: null }, 400)
    }

    const siteId = readSiteId(c, body)
    if (!siteId) {
      return c.json({ status: 400, msg: 'Select a site (site_id / X-Site-Id)', data: null }, 400)
    }
    const domains: KbDomain[] | undefined = body.domain ? [body.domain] : undefined
    const results = await searchKnowledge(c.env, query, {
      domains,
      relProductId: body.productId,
      siteId,
      topK: body.topK || 5,
      minScore: 0.1
    })

    return c.json({ status: 200, msg: 'ok', data: results }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Debug query failed: ' + err.message, data: null }, 500)
  }
})

// 一键从 CMS 产品与文章导入知识库 (避免重复录入)
kbRouter.post('/admin/kb/sync-from-cms', async (c) => {
  try {
    const siteId = readSiteId(c)
    if (!siteId) {
      return c.json({ status: 400, msg: 'Select a site (site_id / X-Site-Id)', data: null }, 400)
    }
    let importedCount = 0

    // 1. 同步本站 CMS 产品
    const productsRes = await getCmsProducts(c.env.DB, { siteId, pageSize: 100 })
    for (const p of productsRes.list) {
      const transZh = p.translations_json?.['zh-CN'] || Object.values(p.translations_json || {})[0]
      const title = p.title || transZh?.title || p.slug
      const description = transZh?.description || transZh?.summary || ''
      const spec = typeof transZh?.spec_data === 'object' ? JSON.stringify(transZh.spec_data) : (transZh?.spec_data || '')

      const content = `Product: ${title}
SKU: ${p.sku || '-'}
Brand: ${p.brand || '-'}
Price: ${p.price} ${p.price_currency}
Description:
${description}
${spec ? `Specs:\n${spec}` : ''}`

      const docId = `cms_prod_${siteId}_${p.id}`
      const doc: KbDocument = {
        id: docId,
        site_id: siteId,
        domain: 'product',
        title: `Product: ${title}`,
        content,
        rel_product_id: p.id,
        tags_json: JSON.stringify([p.brand, p.availability].filter(Boolean)),
        chunks_count: 0,
        status: 'ready',
        created_at: Date.now(),
        updated_at: Date.now()
      }

      await saveKbDocument(c.env.DB, doc)
      await indexDocument(c.env, doc)
      importedCount++
    }

    // 2. 同步本站 CMS 文章
    const articlesRes = await getCmsArticles(c.env.DB, { siteId, pageSize: 100 })
    for (const a of articlesRes.list) {
      const transZh = a.translations_json?.['zh-CN'] || Object.values(a.translations_json || {})[0]
      const title = a.title || transZh?.title || a.slug
      const articleContent = transZh?.content || transZh?.summary || ''
      if (!articleContent.trim()) continue

      const content = `Article: ${title}
Author: ${a.author || 'Official'}
Body:
${articleContent}`

      const docId = `cms_art_${siteId}_${a.id}`
      const doc: KbDocument = {
        id: docId,
        site_id: siteId,
        domain: 'support',
        title: `Article: ${title}`,
        content,
        rel_product_id: null,
        tags_json: JSON.stringify(['CMS']),
        chunks_count: 0,
        status: 'ready',
        created_at: Date.now(),
        updated_at: Date.now()
      }

      await saveKbDocument(c.env.DB, doc)
      await indexDocument(c.env, doc)
      importedCount++
    }

    return c.json({ status: 200, msg: `Synced ${importedCount} items into the knowledge base`, data: { count: importedCount } }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'CMS sync failed: ' + err.message, data: null }, 500)
  }
})

// ==================== 3. AI 智能客服引擎与多模型池配置接口 ====================

// 获取 AI 客服引擎配置 (策略、人设与模型池) — 按当前站点，缺省回退全局
kbRouter.get('/admin/kb/ai-config', async (c) => {
  try {
    const siteId = readSiteId(c)
    const cfg = await readAiConfigForSite(c.env.DB, siteId)
    let modelPool = DEFAULT_MODEL_POOL
    if (cfg.poolJson) {
      try {
        const parsed = JSON.parse(cfg.poolJson)
        if (Array.isArray(parsed) && parsed.length > 0) {
          modelPool = normalizeModelPool(parsed)
        }
      } catch (e) {}
    }

    const ticketAutoReply = cfg.ticketAutoReplyStr !== 'false'

    return c.json({
      status: 200,
      msg: 'ok',
      data: {
        strategy: cfg.strategy,
        system_prompt: cfg.systemPrompt,
        model_pool: modelPool,
        ticket_auto_reply: ticketAutoReply,
        site_id: siteId || null
      }
    }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load AI settings: ' + err.message, data: null }, 500)
  }
})

// 保存 AI 客服引擎配置（有站点则写入 site_settings，否则写全局）
kbRouter.post('/admin/kb/ai-config', async (c) => {
  try {
    const body = await c.req.json() as Partial<AiEngineConfig> & { site_id?: string }
    const siteId = readSiteId(c, body)
    const updates: Record<string, string> = {}

    if (body.strategy) {
      updates['ai_reply_strategy'] = body.strategy
    }
    if (body.system_prompt !== undefined) {
      updates['ai_system_prompt'] = body.system_prompt
    }
    if (body.model_pool && Array.isArray(body.model_pool)) {
      updates['ai_model_pool'] = JSON.stringify(normalizeModelPool(body.model_pool))
    }
    if (body.ticket_auto_reply !== undefined) {
      updates['ai_ticket_auto_reply'] = String(body.ticket_auto_reply)
    }

    if (siteId) {
      await updateSiteSettings(c.env.DB, siteId, updates)
    } else {
      await updateSystemSettings(c.env.DB, updates)
    }

    return c.json({ status: 200, msg: 'AI agent settings updated', data: { site_id: siteId || null } }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to save AI settings: ' + err.message, data: null }, 500)
  }
})

// 单通道连通性测试 (供后台点击“测试连接”时调用)
kbRouter.post('/admin/kb/test-channel', async (c) => {
  try {
    const channel = await c.req.json() as AiModelChannel
    if (!channel || !channel.model) {
      return c.json({ status: 400, msg: 'Channel configuration is incomplete', data: null }, 400)
    }

    const testRes = await testAiChannel(c.env, channel)
    return c.json({ status: 200, msg: 'ok', data: testRes }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Test error: ' + err.message, data: null }, 500)
  }
})

// AI 一键多语言批量翻译 (基于模型轮换池，支持文本与保留 HTML 标签)
kbRouter.post('/admin/kb/translate', async (c) => {
  try {
    const body = await c.req.json() as AiTranslateParams
    if (!body || !body.sourceLang || !body.targetLangs || !body.fields) {
      return c.json({ status: 400, msg: 'Missing required translate parameters', data: null }, 400)
    }

    const result = await translateContentWithAi(c.env, body)
    return c.json({ status: 200, msg: 'ok', data: result }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'AI translate error: ' + err.message, data: null }, 500)
  }
})
