/**
 * CMS 路由层
 * 暴露前台公开 API 与后台管理接口
 * 响应格式严格对齐 cizhenyu_payload: { status: 200, msg: 'ok', data: ... }
 */
import { Hono } from 'hono'
import type { Env } from '../types'
import type { CmsCategoryType } from '../../shared/cmsTypes'
import {
  getCmsCategories,
  createCmsCategory,
  updateCmsCategory,
  deleteCmsCategory,
  getCmsArticles,
  getCmsArticleById,
  createCmsArticle,
  updateCmsArticle,
  deleteCmsArticle,
  getCmsProducts,
  getCmsProductById,
  createCmsProduct,
  updateCmsProduct,
  deleteCmsProduct
} from '../db/cms'
import { agentCanAccessSite, resolveSiteFromRequest } from '../db/sites'
import { isErrorResponse, requireAgent } from '../middleware/auth'
import type { Agent } from '../types'

export const cmsRouter = new Hono<{ Bindings: Env }>()

function readSiteId(
  c: { req: { query: (k: string) => string | undefined; header: (k: string) => string | undefined } },
  body?: any
): string {
  return (
    (c.req.query('site_id') || '').trim() ||
    (c.req.header('X-Site-Id') || '').trim() ||
    (typeof body?.site_id === 'string' ? body.site_id.trim() : '')
  )
}

async function requireCmsAgent(c: Parameters<typeof requireAgent>[0]) {
  const agent = await requireAgent(c)
  if (isErrorResponse(agent)) return { error: agent as Response, agent: null as Agent | null }
  return { error: null as Response | null, agent }
}

async function requireAdminSiteAccess(
  c: Parameters<typeof requireAgent>[0],
  siteId: string
): Promise<Response | Agent> {
  const { error, agent } = await requireCmsAgent(c)
  if (error) return error
  if (!siteId) {
    return c.json({ status: 400, msg: 'Select a site (site_id / X-Site-Id)', data: null }, 400)
  }
  if (!(await agentCanAccessSite(c.env.DB, agent!, siteId))) {
    return c.json({ status: 403, msg: 'No permission to access content on this site', data: null }, 403)
  }
  return agent!
}

async function resolvePublicSiteId(c: Parameters<typeof requireAgent>[0]): Promise<string | null> {
  const site = await resolveSiteFromRequest(c.env.DB, c.req.raw)
  if (!site || site.status !== 'active') return null
  return site.id
}

// ==================== 分类接口 (content_category / product_category) ====================

// 公开列表：按 Origin 解析站点
cmsRouter.get('/cms/categories', async (c) => {
  try {
    const siteId = await resolvePublicSiteId(c)
    if (!siteId) {
      return c.json({ status: 403, msg: 'This domain is not registered to a site', data: null }, 403)
    }
    const type = c.req.query('type') as CmsCategoryType | undefined
    const locale = c.req.query('locale') || c.req.query('lang')
    const list = await getCmsCategories(c.env.DB, type, locale, siteId)
    return c.json({ status: 200, msg: 'ok', data: list }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load categories: ' + err.message, data: null }, 500)
  }
})

// 管理端列表
cmsRouter.get('/admin/cms/categories', async (c) => {
  try {
    const siteId = readSiteId(c)
    const access = await requireAdminSiteAccess(c, siteId)
    if (access instanceof Response) return access
    const type = c.req.query('type') as CmsCategoryType | undefined
    const locale = c.req.query('locale') || c.req.query('lang')
    const list = await getCmsCategories(c.env.DB, type, locale, siteId)
    return c.json({ status: 200, msg: 'ok', data: list }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to load categories: ' + err.message, data: null }, 500)
  }
})

// 创建分类（后台接口）
cmsRouter.post('/admin/cms/categories', async (c) => {
  try {
    const body = await c.req.json()
    const siteId = readSiteId(c, body)
    const access = await requireAdminSiteAccess(c, siteId)
    if (access instanceof Response) return access
    if (!body.slug || (!body.name_json && !body.name)) {
      return c.json({ status: 400, msg: 'Category slug and name are required', data: null }, 400)
    }
    const created = await createCmsCategory(c.env.DB, { ...body, site_id: siteId })
    return c.json({ status: 200, msg: 'ok', data: created }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to create category: ' + err.message, data: null }, 500)
  }
})

// 更新分类（后台接口）
cmsRouter.put('/admin/cms/categories/:id', async (c) => {
  try {
    const siteId = readSiteId(c)
    const access = await requireAdminSiteAccess(c, siteId)
    if (access instanceof Response) return access
    const id = c.req.param('id')
    const body = await c.req.json()
    await updateCmsCategory(c.env.DB, id, body)
    return c.json({ status: 200, msg: 'ok', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to update category: ' + err.message, data: null }, 500)
  }
})

// 删除分类（后台接口）
cmsRouter.delete('/admin/cms/categories/:id', async (c) => {
  try {
    const siteId = readSiteId(c)
    const access = await requireAdminSiteAccess(c, siteId)
    if (access instanceof Response) return access
    const id = c.req.param('id')
    await deleteCmsCategory(c.env.DB, id)
    return c.json({ status: 200, msg: 'ok', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'Failed to delete category: ' + err.message, data: null }, 500)
  }
})

