import type { KbDocument, KbChunk, KbDomain, KbDocumentStatus } from '../types'

/**
 * 确保知识库相关的数据库表与索引存在
 * @param db D1Database 实例
 */
export async function ensureKbTables(db: D1Database): Promise<void> {
  try {
    await db.prepare(`
      CREATE TABLE IF NOT EXISTS kb_documents (
        id TEXT PRIMARY KEY,
        site_id TEXT,
        domain TEXT NOT NULL DEFAULT 'support',
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        rel_product_id TEXT,
        tags_json TEXT,
        chunks_count INTEGER DEFAULT 0,
        status TEXT DEFAULT 'ready',
        error_message TEXT,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      )
    `).run()

    await db.prepare(`
      CREATE TABLE IF NOT EXISTS kb_chunks (
        id TEXT PRIMARY KEY,
        document_id TEXT NOT NULL,
        domain TEXT NOT NULL DEFAULT 'support',
        chunk_index INTEGER NOT NULL,
        content TEXT NOT NULL,
        vector_id TEXT NOT NULL,
        site_id TEXT,
        created_at INTEGER NOT NULL
      )
    `).run()

    try {
      await db.prepare('ALTER TABLE kb_documents ADD COLUMN site_id TEXT').run()
    } catch {
      /* already exists */
    }
    try {
      await db.prepare('ALTER TABLE kb_chunks ADD COLUMN site_id TEXT').run()
    } catch {
      /* already exists */
    }

    try {
      await db.prepare('CREATE INDEX IF NOT EXISTS idx_kb_documents_domain ON kb_documents(domain)').run()
      await db.prepare('CREATE INDEX IF NOT EXISTS idx_kb_documents_product ON kb_documents(rel_product_id)').run()
      await db.prepare('CREATE INDEX IF NOT EXISTS idx_kb_documents_site ON kb_documents(site_id)').run()
      await db.prepare('CREATE INDEX IF NOT EXISTS idx_kb_chunks_document ON kb_chunks(document_id)').run()
      await db.prepare('CREATE INDEX IF NOT EXISTS idx_kb_chunks_vector ON kb_chunks(vector_id)').run()
      await db.prepare('CREATE INDEX IF NOT EXISTS idx_kb_chunks_site ON kb_chunks(site_id)').run()
    } catch (e) {}
  } catch (err) {
    console.error('Failed to ensure KB tables', err)
  }
}

/**
 * 查询知识库文档列表
 * @param db D1Database
 * @param filter 筛选条件
 */
export async function getKbDocuments(
  db: D1Database,
  filter?: {
    domain?: KbDomain
    relProductId?: string
    siteId?: string
    search?: string
    status?: KbDocumentStatus
  }
): Promise<KbDocument[]> {
  await ensureKbTables(db)
  let sql = 'SELECT * FROM kb_documents WHERE 1=1'
  const params: any[] = []

  if (filter?.siteId) {
    sql += ' AND site_id = ?'
    params.push(filter.siteId)
  }
  if (filter?.domain) {
    sql += ' AND domain = ?'
    params.push(filter.domain)
  }
  if (filter?.relProductId) {
    sql += ' AND rel_product_id = ?'
    params.push(filter.relProductId)
  }
  if (filter?.status) {
    sql += ' AND status = ?'
    params.push(filter.status)
  }
  if (filter?.search) {
    sql += ' AND (title LIKE ? OR content LIKE ?)'
    params.push(`%${filter.search}%`, `%${filter.search}%`)
  }

  sql += ' ORDER BY updated_at DESC'

  const stmt = db.prepare(sql).bind(...params)
  const result = await stmt.all<KbDocument>()
  return result.results || []
}

/**
 * 根据 ID 获取单篇文档
 * @param db D1Database
 * @param id 文档 ID
 */
export async function getKbDocumentById(db: D1Database, id: string): Promise<KbDocument | null> {
  await ensureKbTables(db)
  const stmt = db.prepare('SELECT * FROM kb_documents WHERE id = ?').bind(id)
  return await stmt.first<KbDocument>()
}

/**
 * 保存或更新知识库文档
 * @param db D1Database
 * @param doc 文档数据
 */
export async function saveKbDocument(db: D1Database, doc: KbDocument): Promise<void> {
  await ensureKbTables(db)
  const sql = `
    INSERT INTO kb_documents (
      id, site_id, domain, title, content, rel_product_id, tags_json, chunks_count, status, error_message, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      site_id = excluded.site_id,
      domain = excluded.domain,
      title = excluded.title,
      content = excluded.content,
      rel_product_id = excluded.rel_product_id,
      tags_json = excluded.tags_json,
      chunks_count = excluded.chunks_count,
      status = excluded.status,
      error_message = excluded.error_message,
      updated_at = excluded.updated_at
  `
  await db.prepare(sql).bind(
    doc.id,
    doc.site_id || null,
    doc.domain,
    doc.title,
    doc.content,
    doc.rel_product_id || null,
    doc.tags_json || null,
    doc.chunks_count || 0,
    doc.status || 'ready',
    doc.error_message || null,
    doc.created_at,
    doc.updated_at
  ).run()
}

/**
 * 批量插入切片
 * @param db D1Database
 * @param chunks 切片数组
 */
export async function saveKbChunks(db: D1Database, chunks: KbChunk[]): Promise<void> {
  if (!chunks.length) return
  await ensureKbTables(db)

  // 批量分批提交，避免超出 SQLite 变量限制
  const batchSize = 50
  for (let i = 0; i < chunks.length; i += batchSize) {
    const batch = chunks.slice(i, i + batchSize)
    const statements = batch.map(chunk =>
      db.prepare(`
        INSERT INTO kb_chunks (id, document_id, domain, chunk_index, content, vector_id, site_id, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        chunk.id,
        chunk.document_id,
        chunk.domain,
        chunk.chunk_index,
        chunk.content,
        chunk.vector_id,
        chunk.site_id || null,
        chunk.created_at
      )
    )
    await db.batch(statements)
  }
}

/**
 * 删除某文档名下的所有切片
 * @param db D1Database
 * @param documentId 文档 ID
 */
export async function deleteKbChunksByDocumentId(db: D1Database, documentId: string): Promise<string[]> {
  await ensureKbTables(db)
  // 先取 vector_id 方便同步清理 Vectorize
  const rows = await db.prepare('SELECT vector_id FROM kb_chunks WHERE document_id = ?').bind(documentId).all<{ vector_id: string }>()
  const vectorIds = (rows.results || []).map(r => r.vector_id)

  await db.prepare('DELETE FROM kb_chunks WHERE document_id = ?').bind(documentId).run()
  return vectorIds
}

/**
 * 删除知识库文档及其切片
 * @param db D1Database
 * @param id 文档 ID
 */
export async function deleteKbDocument(db: D1Database, id: string): Promise<string[]> {
  const vectorIds = await deleteKbChunksByDocumentId(db, id)
  await db.prepare('DELETE FROM kb_documents WHERE id = ?').bind(id).run()
  return vectorIds
}

/**
 * 根据向量库检索出来的 vector_id 批量获取切片内容
 * @param db D1Database
 * @param vectorIds 向量唯一标识数组
 */
export async function getKbChunksByVectorIds(db: D1Database, vectorIds: string[]): Promise<KbChunk[]> {
  if (!vectorIds || vectorIds.length === 0) return []
  await ensureKbTables(db)

  const placeholders = vectorIds.map(() => '?').join(',')
  const stmt = db.prepare(`SELECT * FROM kb_chunks WHERE vector_id IN (${placeholders})`).bind(...vectorIds)
  const res = await stmt.all<KbChunk>()
  return res.results || []
}

/**
 * 更新文档索引状态
 * @param db D1Database
 * @param id 文档 ID
 * @param status 状态
 * @param chunksCount 切片数
 * @param errorMessage 错误消息
 */
export async function updateKbDocumentStatus(
  db: D1Database,
  id: string,
  status: KbDocumentStatus,
  chunksCount?: number,
  errorMessage?: string
): Promise<void> {
  await ensureKbTables(db)
  let sql = 'UPDATE kb_documents SET status = ?, updated_at = ?'
  const params: any[] = [status, Date.now()]

  if (typeof chunksCount === 'number') {
    sql += ', chunks_count = ?'
    params.push(chunksCount)
  }
  if (errorMessage !== undefined) {
    sql += ', error_message = ?'
    params.push(errorMessage)
  }

  sql += ' WHERE id = ?'
  params.push(id)
  await db.prepare(sql).bind(...params).run()
}
